INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (0, 'the-fool', 'major', NULL, 0, 'cards/major-00') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (0, 'en', 'The Fool', '["beginnings","spontaneity","leap of faith"]', '["recklessness","hesitation","poor timing"]', 'A fresh start is asking for your yes. Pack light, stay curious, and take the first step even if the path ahead is still foggy.', 'Pause before you leap. You may be holding back from a start you are ready for, or rushing into one you have not thought through.', 'New romance or a playful reset — stay open, not naive.', 'A new role or venture favors the bold beginner.', 'Small brave bets beat big blind ones.', 'Move your body; watch for careless knocks.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (0, 'th', 'คนโง่', '["การเริ่มต้น","ความเป็นธรรมชาติ","ความกล้าเสี่ยง"]', '["ความประมาท","ความลังเล","จังหวะที่ไม่ดี"]', 'จุดเริ่มต้นใหม่กำลังเรียกหาคำตอบตกลงของคุณ เก็บของให้น้อย อยากรู้อยากเห็นเข้าไว้ แล้วก้าวออกไปแม้ทางข้างหน้ายังไม่ชัด', 'หยุดคิดก่อนกระโดด ไม่เช่นนั้นคุณอาจรั้งตัวเองจากการเริ่มต้นที่พร้อมแล้ว หรือพุ่งเข้าไปโดยยังไม่ได้คิดให้รอบคอบ', 'ความรักครั้งใหม่หรือการเริ่มกันใหม่แบบสดใส เปิดใจแต่อย่าหลับหูหลับตา', 'งานใหม่หรือโปรเจกต์ใหม่เข้าข้างคนที่กล้าเริ่ม', 'กล้าเล็กๆ ดีกว่าทุ่มแบบไม่คิด', 'ขยับร่างกายบ้าง ระวังอุบัติเหตุเล็กๆ จากความซุ่มซ่าม') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (1, 'the-magician', 'major', NULL, 1, 'cards/major-01') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (1, 'en', 'The Magician', '["skill","focus","making it happen"]', '["scattered energy","untapped talent","trickery"]', 'You already have every tool this needs. Pick one goal, focus your skill on it, and act — this is a week for doing, not doubting.', 'Your talent is leaking into too many directions, or someone is selling confidence they do not have. Narrow down and verify.', 'Charm is high — use it honestly, not to impress.', 'A skill you underrate is exactly what the task needs.', 'Negotiate; you have more leverage than you think.', 'Channel restless energy into one healthy routine.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (1, 'th', 'นักมายากล', '["ทักษะ","สมาธิ","การลงมือทำ"]', '["พลังกระจัดกระจาย","พรสวรรค์ที่ยังไม่ได้ใช้","เล่ห์เหลี่ยม"]', 'คุณมีเครื่องมือครบทุกอย่างที่งานนี้ต้องการแล้ว เลือกเป้าหมายเดียว โฟกัสทักษะลงไป แล้วลงมือทำ สัปดาห์นี้มีไว้ทำ ไม่ใช่ไว้สงสัย', 'พรสวรรค์ของคุณกำลังรั่วไปหลายทาง หรือมีคนขายความมั่นใจที่เขาไม่มี เลือกให้แคบลงและตรวจสอบให้ดี', 'เสน่ห์แรง ใช้อย่างจริงใจ ไม่ใช่เพื่อโอ้อวด', 'ทักษะที่คุณประเมินค่าต่ำไป คือสิ่งที่งานนี้ต้องการพอดี', 'ต่อรองได้ คุณมีแต้มต่อมากกว่าที่คิด', 'เปลี่ยนพลังที่อยู่ไม่สุขให้เป็นกิจวัตรดีๆ สักอย่าง') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (2, 'the-high-priestess', 'major', NULL, 2, 'cards/major-02') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (2, 'en', 'The High Priestess', '["intuition","mystery","quiet knowing"]', '["ignoring your gut","secrets","noise over signal"]', 'The answer is already in you. Get quiet, notice what you keep circling back to, and trust the pull before you can explain it.', 'You are overriding your own knowing — with other people''s opinions, or with busyness. Secrets (kept or kept from you) need daylight.', 'Pay attention to what is unsaid between you.', 'Wait one beat before committing; information is still surfacing.', 'Read the fine print; something is unstated.', 'Your body is signaling — sleep, rest, listen.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (2, 'th', 'นักบวชหญิง', '["สัญชาตญาณ","ความลึกลับ","ความรู้เงียบๆ ในใจ"]', '["เมินเสียงในใจ","ความลับ","เสียงรบกวนกลบสัญญาณ"]', 'คำตอบอยู่ในตัวคุณแล้ว ทำใจให้เงียบ สังเกตสิ่งที่คุณวนกลับไปคิดถึง แล้วเชื่อแรงดึงนั้นก่อนที่คุณจะอธิบายมันได้', 'คุณกำลังกลบความรู้ของตัวเองด้วยความเห็นคนอื่นหรือความยุ่ง ความลับ (ที่คุณเก็บไว้หรือที่คนอื่นปิดคุณ) ต้องการแสงสว่าง', 'ใส่ใจสิ่งที่ไม่ได้พูดออกมาระหว่างคุณ', 'ช้าอีกนิดก่อนตัดสินใจ ข้อมูลยังโผล่มาไม่ครบ', 'อ่านตัวหนังสือเล็กๆ มีบางอย่างที่ไม่ได้บอกไว้', 'ร่างกายกำลังส่งสัญญาณ นอน พัก ฟังมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (3, 'the-empress', 'major', NULL, 3, 'cards/major-03') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (3, 'en', 'The Empress', '["nurture","abundance","creativity"]', '["neglect","smothering","blocked creativity"]', 'Tend what you want to grow — a project, a relationship, yourself. Comfort, beauty, and patience compound into abundance.', 'You are pouring out with nothing coming back in, or gripping too tightly. Refill your own cup first; loosen the grip.', 'Warmth and care deepen the bond; let yourself receive too.', 'Mentor, create, make things beautiful — it pays.', 'Steady nurturing grows savings; avoid comfort overspending.', 'Rest, good food, nature — indulge the senses kindly.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (3, 'th', 'จักรพรรดินี', '["การดูแล","ความอุดมสมบูรณ์","ความคิดสร้างสรรค์"]', '["การละเลย","การประคบประหงมเกินไป","ความคิดสร้างสรรค์ติดขัด"]', 'ดูแลสิ่งที่อยากให้เติบโต ไม่ว่าจะงาน ความสัมพันธ์ หรือตัวคุณเอง ความสบาย ความงาม และความอดทนจะทบต้นเป็นความอุดมสมบูรณ์', 'คุณกำลังเทออกไปโดยไม่มีอะไรไหลกลับมา หรือกอดแน่นเกินไป เติมถ้วยตัวเองก่อน แล้วคลายมือออก', 'ความอบอุ่นและการดูแลทำให้สายสัมพันธ์ลึกขึ้น ปล่อยให้ตัวเองได้รับบ้าง', 'สอนงาน สร้างสรรค์ ทำสิ่งต่างๆ ให้สวย มันคุ้มค่า', 'การดูแลอย่างสม่ำเสมอทำให้เงินเก็บงอก ระวังใช้เงินเกินตัวเพื่อความสบาย', 'พักผ่อน อาหารดี ธรรมชาติ ปรนเปรอประสาทสัมผัสอย่างอ่อนโยน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (4, 'the-emperor', 'major', NULL, 4, 'cards/major-04') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (4, 'en', 'The Emperor', '["structure","authority","steady control"]', '["rigidity","control issues","weak boundaries"]', 'Build the frame and the picture will hold. Set clear rules, budgets, and boundaries — order now buys freedom later.', 'Too rigid or too loose: either control is choking the life out, or nothing is holding. Adjust the structure, not the goal.', 'Commitment needs clear agreements, not assumptions.', 'Process, hierarchy, and follow-through win the day.', 'Budget like an emperor: every baht has a post.', 'Routine and discipline beat motivation.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (4, 'th', 'จักรพรรดิ', '["โครงสร้าง","อำนาจ","การควบคุมที่มั่นคง"]', '["ความแข็งทื่อ","ปัญหาการควบคุม","ขอบเขตที่อ่อนแอ"]', 'สร้างกรอบให้ดี แล้วภาพจะไม่หลุด ตั้งกฎ งบ และขอบเขตให้ชัด ความเป็นระเบียบวันนี้ซื้ออิสรภาพวันหน้า', 'แข็งเกินไปหรือหลวมเกินไป ไม่การควบคุมกำลังบีบชีวิตออกไป ก็ไม่มีอะไรยึดไว้เลย ปรับโครงสร้าง ไม่ใช่เป้าหมาย', 'ความผูกพันต้องการข้อตกลงที่ชัด ไม่ใช่การเดาใจ', 'ระบบ ลำดับขั้น และการทำจนจบคือผู้ชนะวันนี้', 'ทำงบแบบจักรพรรดิ เงินทุกบาทต้องมีที่อยู่', 'กิจวัตรและวินัยชนะแรงบันดาลใจ') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (5, 'the-hierophant', 'major', NULL, 5, 'cards/major-05') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (5, 'en', 'The Hierophant', '["tradition","guidance","belonging"]', '["empty rules","rebellion","bad advice"]', 'Tried paths and wise guides have something for you. Learn the tradition first — then decide what to keep and what to reshape.', 'Rules for rules'' sake are in the way. Question the doctrine, the guru, the ''we have always done it this way''.', 'Shared values and rituals hold you together.', 'A mentor, course, or institution opens the next door.', 'Conventional advice fits now; skip exotic schemes.', 'Trust established care; get a second opinion if uneasy.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (5, 'th', 'พระสันตะปาปา', '["ประเพณี","คำแนะนำ","ความรู้สึกเป็นส่วนหนึ่ง"]', '["กฎที่ว่างเปล่า","การกบฏ","คำแนะนำที่ผิด"]', 'เส้นทางที่คนเดินมาแล้วและครูที่ดีมีบางอย่างให้คุณ เรียนประเพณีให้รู้ก่อน แล้วค่อยเลือกว่าจะเก็บอะไรและปรับอะไร', 'กฎเพื่อกฎกำลังขวางทาง ตั้งคำถามกับหลักคำสอน กับครู กับคำว่า ''เราทำกันมาแบบนี้ตลอด''', 'ค่านิยมและพิธีกรรมร่วมกันคือสิ่งที่ยึดคุณไว้', 'พี่เลี้ยง คอร์ส หรือสถาบันจะเปิดประตูบานต่อไป', 'คำแนะนำแบบดั้งเดิมเหมาะตอนนี้ ข้ามแผนพิสดารไปก่อน', 'เชื่อการดูแลที่เป็นมาตรฐาน ถ้าไม่สบายใจขอความเห็นที่สอง') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (6, 'the-lovers', 'major', NULL, 6, 'cards/major-06') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (6, 'en', 'The Lovers', '["union","choice","alignment"]', '["misalignment","temptation","avoided choice"]', 'A union — of people or of values — is the heart of this. Choose what you truly align with, and let the choice be wholehearted.', 'Something is off-key: values clashing, a third pull, or a decision postponed. Name the misalignment before it names you.', 'Deep bond, real choice. Choose each other daily.', 'Partnership and shared vision beat solo grinding.', 'Align spending with what you actually value.', 'Balance caring for others with caring for yourself.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (6, 'th', 'คู่รัก', '["ความเป็นหนึ่งเดียว","การเลือก","ความสอดคล้อง"]', '["ความไม่ลงรอย","สิ่งล่อใจ","การเลี่ยงการเลือก"]', 'ความเป็นหนึ่งเดียว ไม่ว่าจะของคนหรือของค่านิยม คือหัวใจของเรื่องนี้ เลือกสิ่งที่คุณสอดคล้องด้วยจริงๆ และเลือกอย่างเต็มหัวใจ', 'มีบางอย่างไม่ลงคีย์ ค่านิยมปะทะกัน มีแรงดึงที่สาม หรือการตัดสินใจที่ถูกเลื่อน ตั้งชื่อความไม่ลงรอยก่อนมันจะตั้งชื่อคุณ', 'สายสัมพันธ์ลึกซึ้ง ทางเลือกที่แท้จริง เลือกกันทุกวัน', 'หุ้นส่วนและวิสัยทัศน์ร่วมชนะการลุยเดี่ยว', 'ใช้เงินให้ตรงกับสิ่งที่คุณให้ค่าจริงๆ', 'สมดุลระหว่างดูแลคนอื่นกับดูแลตัวเอง') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (7, 'the-chariot', 'major', NULL, 7, 'cards/major-07') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (7, 'en', 'The Chariot', '["drive","victory","direction"]', '["scattered drive","force without steering","delays"]', 'Grip the reins and move. Opposing pulls resolve when you commit to one direction — victory comes through focused will.', 'You are revving with no steering, or pushing a wall. Re-aim, drop a competing goal, then drive again.', 'Steer the relationship somewhere on purpose; drift kills it.', 'Ambitious push now — keep every horse facing one way.', 'Drive toward one money goal; stop splitting fuel.', 'Directed effort (training plan, sleep hours) works.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (7, 'th', 'รถศึก', '["แรงขับ","ชัยชนะ","ทิศทาง"]', '["แรงขับกระจัดกระจาย","แรงโดยไม่มีพวงมาลัย","ความล่าช้า"]', 'จับบังเหียนแล้วเคลื่อนออก แรงดึงที่สวนกันจะคลี่คลายเมื่อคุณเลือกทิศเดียว ชัยชนะมาจากเจตจำนงที่โฟกัส', 'คุณกำลังเร่งเครื่องโดยไม่เลี้ยว หรือกำลังดันกำแพง เล็งใหม่ ทิ้งเป้าหมายที่แย่งกัน แล้วขับต่อ', 'พาความสัมพันธ์ไปสักทางอย่างตั้งใจ การปล่อยไหลฆ่ามันได้', 'ดันเต็มที่ตอนนี้ ให้ม้าทุกตัวหันหน้าไปทางเดียว', 'ขับไปสู่เป้าหมายเงินข้อเดียว เลิกแบ่งน้ำมัน', 'ความพยายามที่มีทิศ (แผนซ้อม ชั่วโมงการนอน) ได้ผล') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (8, 'strength', 'major', NULL, 8, 'cards/major-08') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (8, 'en', 'Strength', '["courage","patience","gentle power"]', '["force","self-doubt","burnout"]', 'Real strength is gentle: patience with yourself, courage without noise. Tame the lion with calm persistence, not the whip.', 'You are muscling through on fumes, or doubting a strength you actually have. Soften the grip; rest is part of power.', 'Patience and softness tame tensions; no ultimatums.', 'Quiet competence outlasts loud pressure.', 'Steady hands; avoid panic moves.', 'Gentle consistency heals more than heroic bursts.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (8, 'th', 'พลัง', '["ความกล้า","ความอดทน","พลังอันอ่อนโยน"]', '["การใช้กำลัง","ความสงสัยในตัวเอง","ภาวะหมดไฟ"]', 'พลังที่แท้จริงนั้นอ่อนโยน อดทนกับตัวเอง กล้าโดยไม่ต้องเสียงดัง เชื่องสิงโตด้วยความนิ่งที่ยืนหยัด ไม่ใช่แส้', 'คุณกำลังฝืนด้วยแรงที่เหลือน้อย หรือกำลังสงสัยพลังที่ตัวเองมีจริงๆ คลายมือลง การพักคือส่วนหนึ่งของพลัง', 'ความอดทนและความอ่อนโยนสยบความตึง อย่ายื่นคำขาด', 'ความสามารถเงียบๆ อยู่ยาวกว่าแรงกดดันเสียงดัง', 'มือต้องนิ่ง อย่าขยับเพราะตื่นตระหนก', 'ความสม่ำเสมออย่างอ่อนโยนรักษามากกว่าฮึดเป็นพักๆ') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (9, 'the-hermit', 'major', NULL, 9, 'cards/major-09') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (9, 'en', 'The Hermit', '["solitude","reflection","inner light"]', '["isolation","avoidance","lost light"]', 'Step back and go inward for a while. Fewer voices, one lantern: your own experience will show the next step.', 'Solitude has curdled into isolation, or you are dodging the quiet work. Reconnect — with one person, or with yourself.', 'A little space clarifies; too much starves. Say what you need.', 'Deep work beats meetings this week; document as you go.', 'Review alone before any joint decision.', 'Restorative solitude: sleep, walks, less screen.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (9, 'th', 'ฤๅษี', '["ความสันโดษ","การทบทวน","แสงในใจ"]', '["ความโดดเดี่ยว","การหลีกเลี่ยง","แสงที่ดับไป"]', 'ถอยออกมาอยู่กับตัวเองสักพัก เสียงน้อยลง ตะเกียงดวงเดียว ประสบการณ์ของคุณเองจะชี้ก้าวต่อไป', 'ความสันโดษกลายเป็นความโดดเดี่ยว หรือคุณกำลังเลี่ยงงานเงียบๆ ที่ต้องทำ เชื่อมต่อใหม่ กับใครสักคน หรือกับตัวเอง', 'พื้นที่เล็กๆ ทำให้ชัด แต่พื้นที่มากไปทำให้แห้งเหี่ยว บอกสิ่งที่ต้องการ', 'งานลึกชนะการประชุมสัปดาห์นี้ จดไว้ระหว่างทำด้วย', 'ทบทวนคนเดียวก่อนตัดสินใจร่วมกับใคร', 'สันโดษเพื่อฟื้นฟู นอน เดิน หน้าจอน้อยลง') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (10, 'wheel-of-fortune', 'major', NULL, 10, 'cards/major-10') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (10, 'en', 'Wheel of Fortune', '["turning point","luck","cycles"]', '["bad timing","resisting change","stuck wheel"]', 'The wheel is turning in your favor. Ride the upswing: say yes to the opening, and remember luck favors the ready.', 'Timing is off or change feels forced. Do not fight the cycle — stabilize what you can and wait for the turn.', 'A turning point: ride it together, not against each other.', 'Fortune shifts — position yourself where it lands.', 'Upswing favors action; downswing favors saving.', 'Cycles pass; support the body through the low part.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (10, 'th', 'กงล้อแห่งโชคชะตา', '["จุดเปลี่ยน","โชค","วัฏจักร"]', '["จังหวะไม่ดี","ต้านการเปลี่ยนแปลง","ล้อที่ติด"]', 'กงล้อกำลังหมุนเข้าข้างคุณ ขี่คลื่นขาขึ้นนี้ไป ตอบรับโอกาส และจำไว้ว่าโชคเข้าข้างคนพร้อม', 'จังหวะไม่เข้าหรือการเปลี่ยนแปลงรู้สึกถูกบังคับ อย่าสู้กับวัฏจักร ประคองสิ่งที่ประคองได้แล้วรอจังหวะหมุน', 'จุดเปลี่ยน ขี่ไปด้วยกัน ไม่ใช่สวนกัน', 'โชคกำลังย้ายที่ ไปยืนตรงที่มันจะลง', 'ขาขึ้นเหมาะลงมือ ขาลงเหมาะเก็บ', 'วัฏจักรผ่านไป ประคองร่างกายช่วงขาลง') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (11, 'justice', 'major', NULL, 11, 'cards/major-11') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (11, 'en', 'Justice', '["fairness","truth","consequences"]', '["bias","unfairness","avoided reckoning"]', 'Weigh it honestly and call it fairly. Truth, contracts, and consequences are in focus — act so your side stays clean.', 'Something is tilted: bias (yours or theirs), blame-shifting, or a bill coming due. Rebalance before it compounds.', 'Fair give-and-take; name imbalances kindly.', 'Contracts, reviews, credit where due — document everything.', 'Debts, taxes, fairness in splits: settle cleanly.', 'Honest accounting of habits; adjust without shame.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (11, 'th', 'ความยุติธรรม', '["ความยุติธรรม","ความจริง","ผลที่ตามมา"]', '["อคติ","ความไม่ยุติธรรม","การเลี่ยงผล"]', 'ชั่งอย่างซื่อสัตย์แล้วตัดสินอย่างเป็นธรรม ความจริง สัญญา และผลที่ตามมากำลังอยู่ในโฟกัส ทำเพื่อให้ฝั่งคุณสะอาด', 'มีบางอย่างเอียง อคติ (ของคุณหรือของเขา) การโยนความผิด หรือบิลที่กำลังจะมา ปรับสมดุลก่อนมันทบต้น', 'ให้และรับอย่างเป็นธรรม ตั้งชื่อความไม่สมดุลอย่างอ่อนโยน', 'สัญญา การประเมิน เครดิตที่ควรได้ จดทุกอย่าง', 'หนี้ ภาษี การแบ่งที่แฟร์ เคลียร์ให้สะอาด', 'ซื่อสัตย์กับนิสัยตัวเอง ปรับโดยไม่ต้องอาย') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (12, 'the-hanged-man', 'major', NULL, 12, 'cards/major-12') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (12, 'en', 'The Hanged Man', '["pause","new angle","surrender"]', '["stalling","martyrdom","forced sacrifice"]', 'Hang loose on purpose. Flip the viewpoint — the answer looks different upside down — and let timing do its half.', 'The pause has expired into a stall, or you are suffering for show. Either move or admit you are choosing to wait.', 'Stop pushing; see it from their angle for a week.', 'Delay is data. Use the waiting productively.', 'Hold position; no heroics in fog.', 'Rest is the treatment; stop negotiating with it.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (12, 'th', 'คนแขวน', '["การหยุด","มุมมองใหม่","การปล่อยวาง"]', '["การยืดเยื้อ","การเป็นเหยื่อ","การเสียสละที่ถูกบังคับ"]', 'ห้อยตัวนิ่งๆ อย่างตั้งใจ พลิกมุมมอง คำตอบดูต่างออกไปเมื่อกลับหัว แล้วปล่อยให้จังหวะเวลาทำหน้าที่ครึ่งหนึ่งของมัน', 'การหยุดหมดอายุกลายเป็นการยืดเยื้อ หรือคุณกำลังทนทุกข์เพื่อโชว์ ไม่ขยับก็ยอมรับว่าคุณเลือกจะรอ', 'เลิกดัน มองจากมุมเขาสักสัปดาห์', 'ความล่าช้าคือข้อมูล ใช้เวลารอให้เกิดประโยชน์', 'ถือที่ไว้ อย่าเป็นฮีโร่ในหมอก', 'การพักคือยา เลิกต่อรองกับมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (13, 'death', 'major', NULL, 13, 'cards/major-13') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (13, 'en', 'Death', '["endings","release","transformation"]', '["clinging","stuck grief","refused ending"]', 'Something is over so something can begin. Grieve it, thank it, lay it down — the transformation needs the empty hands.', 'You are dragging what already ended. The longer the grip, the heavier the cost; release is overdue, not optional.', 'An old pattern must die for love to live.', 'End the dead project; free the energy.', 'Cut the losing line; mourn the sunk cost once.', 'Release one habit that belongs to an older you.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (13, 'th', 'ความตาย', '["การจบ","การปล่อย","การแปรเปลี่ยน"]', '["การยึดติด","ความโศกที่ค้าง","การปฏิเสธการจบ"]', 'บางอย่างจบลงเพื่อให้บางอย่างเริ่มได้ เศร้าให้มัน ขอบคุณมัน วางมันลง การแปรเปลี่ยนต้องการมือที่ว่าง', 'คุณกำลังลากสิ่งที่จบไปแล้ว ยิ่งกำนานยิ่งแพง การปล่อยเลยกำหนดแล้ว ไม่ใช่ทางเลือก', 'รูปแบบเก่าต้องตาย ความรักถึงจะอยู่ได้', 'จบโปรเจกต์ที่ตายแล้ว ปล่อยพลังออกมา', 'ตัดสายที่ขาดทุน เศร้ากับต้นทุนจมครั้งเดียวพอ', 'ปล่อยนิสัยหนึ่งที่เป็นของตัวคุณคนเก่า') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (14, 'temperance', 'major', NULL, 14, 'cards/major-14') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (14, 'en', 'Temperance', '["balance","moderation","alchemy"]', '["excess","imbalance","forced mix"]', 'Mix, don''t swing. Small steady blends — work and rest, give and take — turn ordinary days into quiet gold.', 'Too much of something (or someone) has tipped the scales. Cut back to the middle path; extremes are billing you.', 'Blend, don''t merge. Keep your own flavor.', 'Sustainable pace; mix deep work with recovery.', 'Middle path: save some, enjoy some.', 'Moderation heals; extremes bill later.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (14, 'th', 'ความพอดี', '["ความสมดุล","ความพอดี","การผสมผสาน"]', '["ความเกินพอดี","ความไม่สมดุล","การผสมที่ฝืน"]', 'ผสม อย่าเหวี่ยง การผสมเล็กๆ อย่างสม่ำเสมอ งานกับการพัก ให้กับรับ เปลี่ยนวันธรรมดาเป็นทองเงียบๆ', 'บางอย่างมากเกินไปจนตาชั่งเอียง กลับมาทางสายกลาง ทางสุดโต่งกำลังเก็บเงินคุณ', 'ผสม อย่ากลืน ยังคงรสชาติของตัวเองไว้', 'จังหวะที่ยั่งยืน ผสมงานลึกกับการฟื้นตัว', 'ทางสายกลาง เก็บส่วนหนึ่ง ใช้ส่วนหนึ่ง', 'ความพอดีรักษา ทางสุดโต่งเก็บเงินทีหลัง') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (15, 'the-devil', 'major', NULL, 15, 'cards/major-15') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (15, 'en', 'The Devil', '["patterns","temptation","shadow"]', '["breaking free","facing shadow","looser chains"]', 'Look honestly at the chain: the habit, the story, the comfort you chose. Naming it loosens it — shame tightens it.', 'The chains are loosening. Keep walking out: one honest day at a time, and do not romanticize the cage.', 'Obsession or control dressed as passion — call it out.', 'Golden handcuffs? Price your freedom honestly.', 'Spending loops and shiny traps — freeze one card.', 'Face the coping habit; replace, don''t just remove.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (15, 'th', 'ปีศาจ', '["รูปแบบเดิมๆ","สิ่งล่อใจ","เงามืด"]', '["การหลุดพ้น","การเผชิญเงา","โซ่ที่คลาย"]', 'มองโซ่ตรงๆ นิสัย เรื่องเล่า ความสบายที่คุณเลือก การตั้งชื่อมันทำให้มันคลาย ความอับอายทำให้มันแน่น', 'โซ่กำลังคลาย เดินออกไปต่อ วันซื่อสัตย์ทีละวัน และอย่าโรแมนติกกับกรง', 'ความหลงหรือการควบคุมที่แต่งตัวเป็นความหลงใหล เรียกชื่อมันออกมา', 'กุญแจมือทอง? ตั้งราคาอิสรภาพอย่างซื่อสัตย์', 'วงจรใช้เงินและกับดักแวววาว แช่แข็งบัตรสักใบ', 'เผชิญนิสัยรับมือ หาอย่างอื่นแทน ไม่ใช่แค่เลิก') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (16, 'the-tower', 'major', NULL, 16, 'cards/major-16') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (16, 'en', 'The Tower', '["upheaval","revelation","sudden change"]', '["resisted collapse","slow leak","rebuilding"]', 'What was shaky is falling — let it. Towers fall so truer ones rise; save what matters, release the rest to the lightning.', 'You are holding up what already cracked, or rebuilding quietly after the bang. Either way: smaller, truer, on rock this time.', 'A shock clears the air — rebuild honest or release.', 'Structures change; be the one who adapts first.', 'Expect the jolt; keep a buffer for falling bricks.', 'Sudden signals need attention now, not later.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (16, 'th', 'หอคอย', '["ความสั่นคลอน","การเปิดเผย","การเปลี่ยนฉับพลัน"]', '["การต้านการพัง","รอยรั่วช้าๆ","การสร้างใหม่"]', 'สิ่งที่โยกเยกกำลังล้ม ปล่อยมัน หอคอยล้มเพื่อให้หอที่แท้กว่าลุกขึ้น เก็บสิ่งที่สำคัญ ปล่อยที่เหลือให้สายฟ้า', 'คุณกำลังค้ำสิ่งที่ร้าวแล้ว หรือกำลังสร้างใหม่เงียบๆ หลังเสียงดัง ไม่ว่าทางไหน เล็กลง แท้ขึ้น บนหินครั้งนี้', 'แรงกระแทกทำให้อากาศชัด สร้างใหม่อย่างซื่อสัตย์หรือปล่อยไป', 'โครงสร้างเปลี่ยน เป็นคนแรกที่ปรับตัว', 'เตรียมรับแรงกระแทก กันสำรองไว้รับอิฐร่วง', 'สัญญาณฉับพลันต้องการความใส่ใจตอนนี้ ไม่ใช่ทีหลัง') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (17, 'the-star', 'major', NULL, 17, 'cards/major-17') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (17, 'en', 'The Star', '["hope","healing","quiet faith"]', '["dimmed hope","healing slowly","faith wobbling"]', 'After the storm, stars. Hope is realistic now: heal gently, wish concretely, and let small steady lights guide you.', 'Hope feels far, but it is dimmed, not dead. Tend one small light — a routine, a person, a page — until it steadies.', 'Healing love: honesty under starlight.', 'Share your vision; hope attracts help.', 'Calm recovery; wish with a plan attached.', 'Healing is underway; support it gently.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (17, 'th', 'ดวงดาว', '["ความหวัง","การเยียวยา","ศรัทธาเงียบๆ"]', '["ความหวังที่หรี่ลง","การเยียวยาช้าๆ","ศรัทธาที่สั่นคลอน"]', 'หลังพายุคือดวงดาว ความหวังเป็นจริงได้ตอนนี้ เยียวยาอย่างอ่อนโยน ปรารถนาอย่างเป็นรูปธรรม แล้วให้แสงเล็กๆ ที่มั่นคงนำทาง', 'ความหวังรู้สึกไกล แต่มันแค่หรี่ ไม่ได้ดับ ดูแลแสงเล็กๆ สักดวง กิจวัตร คน หรือหน้ากระดาษ จนมันนิ่ง', 'ความรักที่เยียวยา ซื่อสัตย์ใต้แสงดาว', 'แชร์วิสัยทัศน์ ความหวังดึงดูดความช่วยเหลือ', 'ฟื้นตัวอย่างสงบ ปรารถนาพร้อมแผน', 'การเยียวยากำลังดำเนิน ประคองมันอย่างอ่อนโยน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (18, 'the-moon', 'major', NULL, 18, 'cards/major-18') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (18, 'en', 'The Moon', '["dreams","uncertainty","the unseen"]', '["clarity returning","named fears","lifting fog"]', 'Things glimmer but do not resolve yet. Trust dreams and hunches, double-check facts, and do not sign in moonlight.', 'Fog is lifting: fears named shrink, confusion untangles. Keep going — daylight is a decision away.', 'Illusions dissolve; see the person, not the projection.', 'Verify before you commit; rumors are loud now.', 'Hidden costs surface — look twice.', 'Sleep and dreams carry messages; rest more.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (18, 'th', 'ดวงจันทร์', '["ความฝัน","ความไม่แน่นอน","สิ่งที่มองไม่เห็น"]', '["ความชัดที่กลับมา","ความกลัวที่ถูกตั้งชื่อ","หมอกที่จาง"]', 'สิ่งต่างๆ วับวาวแต่ยังไม่ชัด เชื่อความฝันและลางสังหรณ์ ตรวจสอบข้อเท็จจริงซ้ำ และอย่าเซ็นอะไรใต้แสงจันทร์', 'หมอกกำลังจาง ความกลัวที่ถูกตั้งชื่อจะหด ความสับสนคลายปม เดินต่อไป แสงกลางวันห่างแค่การตัดสินใจเดียว', 'ภาพลวงตาสลาย มองคนที่เขาเป็น ไม่ใช่ภาพที่คุณฉาย', 'ตรวจสอบก่อนผูกมัด ข่าวลือดังตอนนี้', 'ต้นทุนแฝงโผล่ขึ้นมา ดูสองรอบ', 'การนอนและความฝันมีข้อความมา พักเพิ่ม') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (19, 'the-sun', 'major', NULL, 19, 'cards/major-19') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (19, 'en', 'The Sun', '["joy","clarity","vitality"]', '["clouded joy","delayed success","forced cheer"]', 'Yes — bright, simple yes. Joy, clarity, and energy are yours: celebrate openly and share the warmth around.', 'Clouds, not night: joy delayed or dimmed, success still coming. Do not fake the smile — tend the small good things.', 'Warm, honest, playful — let it show.', 'Visibility and wins; take the bow.', 'Sunny outlook; still budget the picnic.', 'Vitality returns; sunlight, movement, laughter.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (19, 'th', 'ดวงอาทิตย์', '["ความสุข","ความชัดเจน","พลังชีวิต"]', '["ความสุขที่มีเมฆ","ความสำเร็จที่ช้า","ความร่าเริงที่ฝืน"]', 'ใช่ ตกลงอย่างสว่างและเรียบง่าย ความสุข ความชัด และพลังเป็นของคุณ ฉลองอย่างเปิดเผยแล้วแบ่งความอบอุ่นออกไป', 'เมฆ ไม่ใช่กลางคืน ความสุขช้าหรือหรี่ลง แต่ความสำเร็จยังมา อย่าฝืนยิ้ม ดูแลสิ่งดีเล็กๆ', 'อบอุ่น ซื่อสัตย์ สนุก ปล่อยให้เห็น', 'เป็นที่เห็นและชนะ รับเสียงปรบมือ', 'แนวโน้มสดใส แต่ก็ทำงบปิกนิกไว้ด้วย', 'พลังชีวิตกลับมา แดด การขยับ เสียงหัวเราะ') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (20, 'judgement', 'major', NULL, 20, 'cards/major-20') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (20, 'en', 'Judgement', '["awakening","calling","forgiveness"]', '["self-criticism","missed call","unfinished past"]', 'A calling is sounding — rise to the bigger version of you. Forgive the old chapters; answer with changed action.', 'The inner judge is too loud, or you keep missing the call. Turn criticism into instruction; tie up one old thread.', 'Forgive and choose fresh — or admit it is over.', 'Your calling is knocking; answer with a move.', 'Review past money lessons; apply one now.', 'Forgive the body; start the new regimen kindly.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (20, 'th', 'การพิพากษา', '["การตื่นรู้","เสียงเรียก","การให้อภัย"]', '["การตำหนิตัวเอง","เสียงเรียกที่พลาด","อดีตที่ค้าง"]', 'เสียงเรียกกำลังดังขึ้น ลุกสู่ตัวคุณเวอร์ชันที่ใหญ่กว่า ให้อภัยบทเก่าๆ แล้วตอบด้วยการกระทำที่เปลี่ยนไป', 'ผู้พิพากษาในใจดังเกินไป หรือคุณพลาดเสียงเรียกเรื่อยๆ เปลี่ยนคำตำหนิเป็นคำสอน เก็บด้ายเก่าสักเส้นให้จบ', 'ให้อภัยแล้วเลือกใหม่ หรือยอมรับว่ามันจบแล้ว', 'เสียงเรียกกำลังเคาะประตู ตอบด้วยการขยับ', 'ทบทวนบทเรียนเงินในอดีต เอามาใช้สักข้อตอนนี้', 'ให้อภัยร่างกาย เริ่มระบบใหม่ด้วยความอ่อนโยน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (21, 'the-world', 'major', NULL, 21, 'cards/major-21') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (21, 'en', 'The World', '["completion","wholeness","arrival"]', '["loose ends","almost there","unclosed circle"]', 'The circle closes beautifully. Complete it, celebrate it, carry the lesson — a bigger circle is already forming.', 'Nearly there: one loose end keeps the circle open. Tie it, and the completion (and the celebration) unlocks.', 'Wholeness together — or whole on your own. Both count.', 'Finish strong; the credential is the completion.', 'A cycle completes; harvest, then plan the next.', 'Integration: body, mind, and rhythm aligned.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (21, 'th', 'โลก', '["ความสมบูรณ์","ความครบถ้วน","การมาถึง"]', '["ปลายที่ยังไม่เก็บ","เกือบถึง","วงที่ยังไม่ปิด"]', 'วงกลมปิดอย่างสวยงาม ทำให้จบ ฉลองมัน พกบทเรียนไปด้วย วงที่ใหญ่กว่ากำลังก่อตัวแล้ว', 'เกือบถึงแล้ว ปลายที่ยังไม่เก็บเส้นเดียวทำให้วงเปิดอยู่ เก็บมัน แล้วความสมบูรณ์ (และการฉลอง) จะปลดล็อก', 'ความครบถ้วนด้วยกัน หรือครบด้วยตัวเอง ทั้งสองนับ', 'จบให้สวย ใบเบิกทางคือการทำจนจบ', 'วัฏจักรหนึ่งจบ เก็บเกี่ยว แล้ววางแผนรอบต่อไป', 'การประสาน กาย ใจ และจังหวะตรงกัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (22, 'ace-of-wands', 'minor', 'wands', 1, 'cards/wands-01') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (22, 'en', 'Ace of Wands', '["seed","gift","pure potential","drive"]', '["blocked seed","missed gift","hollow start","burnout"]', 'A new seed in this suit''s domain — raw, bright potential. Fire moves it: energy, courage, and momentum.', 'The seed cannot sprout yet: wrong soil, wrong season, or a gift refused. Fire unchecked: haste, burnout, or pride running the show.', 'Passion and playfulness — keep it kind, not competitive.', 'Ambition and initiative open doors; finish what you start.', 'Bold moves need budgets; fund the spark, not the blaze.', 'Move, sweat, discharge — then rest deliberately.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (22, 'th', 'เอซ ไม้เท้า', '["เมล็ด","ของขวัญ","ศักยภาพบริสุทธิ์","แรงขับ"]', '["เมล็ดที่ติดขัด","ของขวัญที่พลาด","การเริ่มที่กลวง","หมดไฟ"]', 'เมล็ดใหม่ในอาณาเขตของไพ่ชุดนี้ ศักยภาพดิบที่สดใส ไฟขับเคลื่อนมัน พลังงาน ความกล้า และโมเมนตัม', 'เมล็ดยังงอกไม่ได้ ดินผิด ฤดูผิด หรือของขวัญที่ถูกปฏิเสธ ไฟที่ไม่ถูกคุม ความรีบร้อน หมดไฟ หรืออีโก้เป็นคนขับ', 'ความหลงใหลและความสนุก ใจดีเข้าไว้ ไม่ใช่แข่งกัน', 'ความทะเยอทะยานและความริเริ่มเปิดประตู ทำที่เริ่มให้จบ', 'การขยับที่กล้าต้องมีงบ หนุนประกาย ไม่ใช่ไฟป่า', 'ขยับ เหงื่อออก ระบาย แล้วพักอย่างตั้งใจ') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (23, 'two-of-wands', 'minor', 'wands', 2, 'cards/wands-02') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (23, 'en', 'Two of Wands', '["balance","partnership","first choice","drive"]', '["imbalance","stalemate","avoided choice","burnout"]', 'Two forces meet: partnership, balance, or the first real choice. Fire moves it: energy, courage, and momentum.', 'The pair is off-balance: stalemate, tension, or a choice dodged. Fire unchecked: haste, burnout, or pride running the show.', 'Passion and playfulness — keep it kind, not competitive.', 'Ambition and initiative open doors; finish what you start.', 'Bold moves need budgets; fund the spark, not the blaze.', 'Move, sweat, discharge — then rest deliberately.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (23, 'th', '2 ไม้เท้า', '["ความสมดุล","หุ้นส่วน","ทางเลือกแรก","แรงขับ"]', '["ความไม่สมดุล","การตัน","ทางเลือกที่เลี่ยง","หมดไฟ"]', 'พลังสองสายมาบรรจบ หุ้นส่วน ความสมดุล หรือทางเลือกจริงครั้งแรก ไฟขับเคลื่อนมัน พลังงาน ความกล้า และโมเมนตัม', 'คู่นี้เสียสมดุล ตัน ตึง หรือทางเลือกที่ถูกเลี่ยง ไฟที่ไม่ถูกคุม ความรีบร้อน หมดไฟ หรืออีโก้เป็นคนขับ', 'ความหลงใหลและความสนุก ใจดีเข้าไว้ ไม่ใช่แข่งกัน', 'ความทะเยอทะยานและความริเริ่มเปิดประตู ทำที่เริ่มให้จบ', 'การขยับที่กล้าต้องมีงบ หนุนประกาย ไม่ใช่ไฟป่า', 'ขยับ เหงื่อออก ระบาย แล้วพักอย่างตั้งใจ') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (24, 'three-of-wands', 'minor', 'wands', 3, 'cards/wands-03') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (24, 'en', 'Three of Wands', '["first fruits","togetherness","expression","drive"]', '["scattered trio","gossip","delayed fruits","burnout"]', 'First fruits: growth shows, people gather, expression flows. Fire moves it: energy, courage, and momentum.', 'The trio frays: miscommunication, gossip, or fruits that need more season. Fire unchecked: haste, burnout, or pride running the show.', 'Passion and playfulness — keep it kind, not competitive.', 'Ambition and initiative open doors; finish what you start.', 'Bold moves need budgets; fund the spark, not the blaze.', 'Move, sweat, discharge — then rest deliberately.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (24, 'th', '3 ไม้เท้า', '["ผลแรก","ความพร้อมหน้า","การแสดงออก","แรงขับ"]', '["สามคนที่แตก","นินทา","ผลที่ช้า","หมดไฟ"]', 'ผลแรก ความเติบโตเริ่มเห็น คนรวมกัน การแสดงออกไหล ไฟขับเคลื่อนมัน พลังงาน ความกล้า และโมเมนตัม', 'สามคนเริ่มขาด การสื่อสารพลาด นินทา หรือผลที่ต้องรอฤดูอีกหน่อย ไฟที่ไม่ถูกคุม ความรีบร้อน หมดไฟ หรืออีโก้เป็นคนขับ', 'ความหลงใหลและความสนุก ใจดีเข้าไว้ ไม่ใช่แข่งกัน', 'ความทะเยอทะยานและความริเริ่มเปิดประตู ทำที่เริ่มให้จบ', 'การขยับที่กล้าต้องมีงบ หนุนประกาย ไม่ใช่ไฟป่า', 'ขยับ เหงื่อออก ระบาย แล้วพักอย่างตั้งใจ') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (25, 'four-of-wands', 'minor', 'wands', 4, 'cards/wands-04') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (25, 'en', 'Four of Wands', '["rest","foundation","pause to hold","drive"]', '["stagnation","rigid hold","rest refused","burnout"]', 'Four walls: rest, consolidate, hold what you built. Fire moves it: energy, courage, and momentum.', 'Rest curdled into rut: clinging to the walls instead of living in the house. Fire unchecked: haste, burnout, or pride running the show.', 'Passion and playfulness — keep it kind, not competitive.', 'Ambition and initiative open doors; finish what you start.', 'Bold moves need budgets; fund the spark, not the blaze.', 'Move, sweat, discharge — then rest deliberately.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (25, 'th', '4 ไม้เท้า', '["การพัก","รากฐาน","การหยุดเพื่อรักษา","แรงขับ"]', '["การนิ่งตาย","การยึดแข็ง","การปฏิเสธการพัก","หมดไฟ"]', 'กำแพงสี่ด้าน พัก ประสาน รักษาสิ่งที่สร้างมา ไฟขับเคลื่อนมัน พลังงาน ความกล้า และโมเมนตัม', 'การพักกลายเป็นร่อง ยึดกำแพงแทนที่จะอยู่ในบ้าน ไฟที่ไม่ถูกคุม ความรีบร้อน หมดไฟ หรืออีโก้เป็นคนขับ', 'ความหลงใหลและความสนุก ใจดีเข้าไว้ ไม่ใช่แข่งกัน', 'ความทะเยอทะยานและความริเริ่มเปิดประตู ทำที่เริ่มให้จบ', 'การขยับที่กล้าต้องมีงบ หนุนประกาย ไม่ใช่ไฟป่า', 'ขยับ เหงื่อออก ระบาย แล้วพักอย่างตั้งใจ') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (26, 'five-of-wands', 'minor', 'wands', 5, 'cards/wands-05') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (26, 'en', 'Five of Wands', '["friction","loss felt","shake-up","drive"]', '["longer conflict","blame","slow recovery","burnout"]', 'Friction with a lesson: loss, conflict, or a shake-up that reveals what stands. Fire moves it: energy, courage, and momentum.', 'The fight drags on or blame spreads; recovery is slow but possible — stop feeding it. Fire unchecked: haste, burnout, or pride running the show.', 'Passion and playfulness — keep it kind, not competitive.', 'Ambition and initiative open doors; finish what you start.', 'Bold moves need budgets; fund the spark, not the blaze.', 'Move, sweat, discharge — then rest deliberately.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (26, 'th', '5 ไม้เท้า', '["แรงเสียดทาน","ความสูญเสียที่รู้สึก","แรงเขย่า","แรงขับ"]', '["ความขัดแย้งที่ยาว","การโทษ","การฟื้นช้า","หมดไฟ"]', 'แรงเสียดทานพร้อมบทเรียน ความสูญเสีย ความขัดแย้ง หรือแรงเขย่าที่เผยให้เห็นสิ่งที่ยืนอยู่ ไฟขับเคลื่อนมัน พลังงาน ความกล้า และโมเมนตัม', 'การสู้ยืดเยื้อหรือการโทษกันลาม การฟื้นช้าแต่เป็นไปได้ เลิกให้อาหารมัน ไฟที่ไม่ถูกคุม ความรีบร้อน หมดไฟ หรืออีโก้เป็นคนขับ', 'ความหลงใหลและความสนุก ใจดีเข้าไว้ ไม่ใช่แข่งกัน', 'ความทะเยอทะยานและความริเริ่มเปิดประตู ทำที่เริ่มให้จบ', 'การขยับที่กล้าต้องมีงบ หนุนประกาย ไม่ใช่ไฟป่า', 'ขยับ เหงื่อออก ระบาย แล้วพักอย่างตั้งใจ') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (27, 'six-of-wands', 'minor', 'wands', 6, 'cards/wands-06') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (27, 'en', 'Six of Wands', '["ease after strain","giving","nostalgia","drive"]', '["strings attached","stuck past","unequal give","burnout"]', 'Breathing room: help given or received, sweetness from the past, smoother water. Fire moves it: energy, courage, and momentum.', 'Giving with strings, or living in the rearview: accept help cleanly, visit the past — do not move back in. Fire unchecked: haste, burnout, or pride running the show.', 'Passion and playfulness — keep it kind, not competitive.', 'Ambition and initiative open doors; finish what you start.', 'Bold moves need budgets; fund the spark, not the blaze.', 'Move, sweat, discharge — then rest deliberately.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (27, 'th', '6 ไม้เท้า', '["ความโล่งหลังเหนื่อย","การให้","ความคิดถึง","แรงขับ"]', '["เงื่อนไขที่ผูก","อดีตที่ติด","การให้ที่ไม่เท่า","หมดไฟ"]', 'ที่หายใจ ความช่วยเหลือที่ให้หรือรับ ความหวานจากอดีต น้ำที่เรียบขึ้น ไฟขับเคลื่อนมัน พลังงาน ความกล้า และโมเมนตัม', 'ให้แบบมีเงื่อนไข หรืออยู่ในกระจกมองหลัง รับความช่วยเหลืออย่างสะอาด แวะอดีต อย่าย้ายกลับเข้าไป ไฟที่ไม่ถูกคุม ความรีบร้อน หมดไฟ หรืออีโก้เป็นคนขับ', 'ความหลงใหลและความสนุก ใจดีเข้าไว้ ไม่ใช่แข่งกัน', 'ความทะเยอทะยานและความริเริ่มเปิดประตู ทำที่เริ่มให้จบ', 'การขยับที่กล้าต้องมีงบ หนุนประกาย ไม่ใช่ไฟป่า', 'ขยับ เหงื่อออก ระบาย แล้วพักอย่างตั้งใจ') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (28, 'seven-of-wands', 'minor', 'wands', 7, 'cards/wands-07') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (28, 'en', 'Seven of Wands', '["assessment","many options","stand your ground","drive"]', '["overwhelm","illusion of choice","defensive crouch","burnout"]', 'Step back and assess: many options, one position to defend, patience before the next move. Fire moves it: energy, courage, and momentum.', 'Too many threads or a defensive crouch: narrow the field, then stand — or strategically yield. Fire unchecked: haste, burnout, or pride running the show.', 'Passion and playfulness — keep it kind, not competitive.', 'Ambition and initiative open doors; finish what you start.', 'Bold moves need budgets; fund the spark, not the blaze.', 'Move, sweat, discharge — then rest deliberately.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (28, 'th', '7 ไม้เท้า', '["การประเมิน","ทางเลือกมาก","รักษาที่ยืน","แรงขับ"]', '["ความท่วมท้น","ภาพลวงของทางเลือก","ท่าตั้งรับ","หมดไฟ"]', 'ถอยมาประเมิน ทางเลือกมาก ที่ยืนที่ต้องรักษา อดทนก่อนขยับต่อไป ไฟขับเคลื่อนมัน พลังงาน ความกล้า และโมเมนตัม', 'ด้ายมากเกินไปหรือท่าตั้งรับ แคบสนามลง แล้วค่อยยืน หรือถอยอย่างมีกลยุทธ์ ไฟที่ไม่ถูกคุม ความรีบร้อน หมดไฟ หรืออีโก้เป็นคนขับ', 'ความหลงใหลและความสนุก ใจดีเข้าไว้ ไม่ใช่แข่งกัน', 'ความทะเยอทะยานและความริเริ่มเปิดประตู ทำที่เริ่มให้จบ', 'การขยับที่กล้าต้องมีงบ หนุนประกาย ไม่ใช่ไฟป่า', 'ขยับ เหงื่อออก ระบาย แล้วพักอย่างตั้งใจ') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (29, 'eight-of-wands', 'minor', 'wands', 8, 'cards/wands-08') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (29, 'en', 'Eight of Wands', '["mastery in motion","focused work","swift change","drive"]', '["scattered effort","perfectionism","too fast","burnout"]', 'Skilled motion: focused work compounds, or change arrives fast — meet it prepared. Fire moves it: energy, courage, and momentum.', 'Effort scattered or perfectionism stalling the line; slow one thing down to speed the whole up. Fire unchecked: haste, burnout, or pride running the show.', 'Passion and playfulness — keep it kind, not competitive.', 'Ambition and initiative open doors; finish what you start.', 'Bold moves need budgets; fund the spark, not the blaze.', 'Move, sweat, discharge — then rest deliberately.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (29, 'th', '8 ไม้เท้า', '["ความชำนาญที่เคลื่อน","งานโฟกัส","การเปลี่ยนที่เร็ว","แรงขับ"]', '["ความพยายามที่แตก","ความสมบูรณ์แบบ","เร็วเกินไป","หมดไฟ"]', 'การเคลื่อนอย่างชำนาญ งานโฟกัสทบต้น หรือการเปลี่ยนมาเร็ว เจอมันอย่างเตรียมพร้อม ไฟขับเคลื่อนมัน พลังงาน ความกล้า และโมเมนตัม', 'ความพยายามกระจัดกระจายหรือความสมบูรณ์แบบทำให้สายพานหยุด ชะลอสิ่งหนึ่งเพื่อให้ทั้งหมดเร็วขึ้น ไฟที่ไม่ถูกคุม ความรีบร้อน หมดไฟ หรืออีโก้เป็นคนขับ', 'ความหลงใหลและความสนุก ใจดีเข้าไว้ ไม่ใช่แข่งกัน', 'ความทะเยอทะยานและความริเริ่มเปิดประตู ทำที่เริ่มให้จบ', 'การขยับที่กล้าต้องมีงบ หนุนประกาย ไม่ใช่ไฟป่า', 'ขยับ เหงื่อออก ระบาย แล้วพักอย่างตั้งใจ') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (30, 'nine-of-wands', 'minor', 'wands', 9, 'cards/wands-09') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (30, 'en', 'Nine of Wands', '["near-complete","wishes","resilience","drive"]', '["nearly-but-stuck","anxiety nights","walled garden","burnout"]', 'Almost whole: wishes close, resilience proven — guard the last stretch with care. Fire moves it: energy, courage, and momentum.', 'So close yet stuck: worry loops or a comfort zone fenced too high. Name the fear, take the final step. Fire unchecked: haste, burnout, or pride running the show.', 'Passion and playfulness — keep it kind, not competitive.', 'Ambition and initiative open doors; finish what you start.', 'Bold moves need budgets; fund the spark, not the blaze.', 'Move, sweat, discharge — then rest deliberately.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (30, 'th', '9 ไม้เท้า', '["เกือบสมบูรณ์","ความปรารถนา","ความอึด","แรงขับ"]', '["เกือบแต่ติด","คืนที่นอนไม่หลับ","สวนที่มีกำแพง","หมดไฟ"]', 'เกือบครบ ความปรารถนาใกล้ ความอึดพิสูจน์แล้ว ประคองช่วงสุดท้ายดีๆ ไฟขับเคลื่อนมัน พลังงาน ความกล้า และโมเมนตัม', 'ใกล้แต่ติด วงจรความกังวลหรือเขตสบายที่รั้วสูงไป ตั้งชื่อความกลัว แล้วก้าวสุดท้าย ไฟที่ไม่ถูกคุม ความรีบร้อน หมดไฟ หรืออีโก้เป็นคนขับ', 'ความหลงใหลและความสนุก ใจดีเข้าไว้ ไม่ใช่แข่งกัน', 'ความทะเยอทะยานและความริเริ่มเปิดประตู ทำที่เริ่มให้จบ', 'การขยับที่กล้าต้องมีงบ หนุนประกาย ไม่ใช่ไฟป่า', 'ขยับ เหงื่อออก ระบาย แล้วพักอย่างตั้งใจ') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (31, 'ten-of-wands', 'minor', 'wands', 10, 'cards/wands-10') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (31, 'en', 'Ten of Wands', '["completion","full circle","legacy","drive"]', '["overfull","crashing end","burden shared badly","burnout"]', 'The full arc of the suit: completion, culmination, what carries forward. Fire moves it: energy, courage, and momentum.', 'Overfull or ending hard: too much carried, or a cycle closing messily — set down, sort out, close clean. Fire unchecked: haste, burnout, or pride running the show.', 'Passion and playfulness — keep it kind, not competitive.', 'Ambition and initiative open doors; finish what you start.', 'Bold moves need budgets; fund the spark, not the blaze.', 'Move, sweat, discharge — then rest deliberately.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (31, 'th', '10 ไม้เท้า', '["ความสมบูรณ์","วงเต็ม","มรดก","แรงขับ"]', '["ล้นเกิน","จุดจบที่กระแทก","ภาระที่แบ่งไม่ดี","หมดไฟ"]', 'ส่วนโค้งเต็มของไพ่ชุดนี้ ความสมบูรณ์ จุดสูงสุด สิ่งที่ส่งต่อ ไฟขับเคลื่อนมัน พลังงาน ความกล้า และโมเมนตัม', 'ล้นหรือจบแบบกระแทก แบกมากเกิน หรือวัฏจักรปิดแบบเละ วางลง จัดการ ปิดให้สะอาด ไฟที่ไม่ถูกคุม ความรีบร้อน หมดไฟ หรืออีโก้เป็นคนขับ', 'ความหลงใหลและความสนุก ใจดีเข้าไว้ ไม่ใช่แข่งกัน', 'ความทะเยอทะยานและความริเริ่มเปิดประตู ทำที่เริ่มให้จบ', 'การขยับที่กล้าต้องมีงบ หนุนประกาย ไม่ใช่ไฟป่า', 'ขยับ เหงื่อออก ระบาย แล้วพักอย่างตั้งใจ') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (32, 'page-of-wands', 'minor', 'wands', 11, 'cards/wands-11') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (32, 'en', 'Page of Wands', '["student","message","fresh curiosity","drive"]', '["gossip","distraction","study skipped","burnout"]', 'The eager student: a message, a new study, curiosity first — beginner''s mind, open notebook. Fire moves it: energy, courage, and momentum.', 'Distracted student: gossip over study, shiny hopping. Pick one page and actually read it. Fire unchecked: haste, burnout, or pride running the show.', 'Passion and playfulness — keep it kind, not competitive.', 'Ambition and initiative open doors; finish what you start.', 'Bold moves need budgets; fund the spark, not the blaze.', 'Move, sweat, discharge — then rest deliberately.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (32, 'th', 'เพจไม้เท้า', '["นักเรียน","ข้อความ","ความอยากรู้สดๆ","แรงขับ"]', '["นินทา","สิ่งรบกวน","การเรียนที่ข้าม","หมดไฟ"]', 'นักเรียนที่กระตือรือร้น ข้อความ การเรียนใหม่ ความอยากรู้ก่อน ใจแบบมือใหม่ สมุดที่เปิด ไฟขับเคลื่อนมัน พลังงาน ความกล้า และโมเมนตัม', 'นักเรียนที่วอกแวก นินทาแทนเรียน กระโดดหาของแวววาว เลือกมาสักหน้าแล้วอ่านจริง ไฟที่ไม่ถูกคุม ความรีบร้อน หมดไฟ หรืออีโก้เป็นคนขับ', 'ความหลงใหลและความสนุก ใจดีเข้าไว้ ไม่ใช่แข่งกัน', 'ความทะเยอทะยานและความริเริ่มเปิดประตู ทำที่เริ่มให้จบ', 'การขยับที่กล้าต้องมีงบ หนุนประกาย ไม่ใช่ไฟป่า', 'ขยับ เหงื่อออก ระบาย แล้วพักอย่างตั้งใจ') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (33, 'knight-of-wands', 'minor', 'wands', 12, 'cards/wands-12') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (33, 'en', 'Knight of Wands', '["charge","quest","momentum","drive"]', '["reckless charge","hot-cold","quest drift","burnout"]', 'The charger: full momentum toward the quest — brave, fast, all-in. Fire moves it: energy, courage, and momentum.', 'Charging past the target or blowing hot and cold: rein in, re-aim, then ride. Fire unchecked: haste, burnout, or pride running the show.', 'Passion and playfulness — keep it kind, not competitive.', 'Ambition and initiative open doors; finish what you start.', 'Bold moves need budgets; fund the spark, not the blaze.', 'Move, sweat, discharge — then rest deliberately.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (33, 'th', 'อัศวินไม้เท้า', '["การพุ่ง","ภารกิจ","โมเมนตัม","แรงขับ"]', '["การพุ่งที่ประมาท","ร้อนหนาว","ภารกิจที่ลอย","หมดไฟ"]', 'ผู้พุ่งทะยาน โมเมนตัมเต็มสู่ภารกิจ กล้า เร็ว ทุ่มหมด ไฟขับเคลื่อนมัน พลังงาน ความกล้า และโมเมนตัม', 'พุ่งเลยเป้าหรือร้อนๆ หนาวๆ ดึงบังเหียน เล็งใหม่ แล้วค่อยขี่ ไฟที่ไม่ถูกคุม ความรีบร้อน หมดไฟ หรืออีโก้เป็นคนขับ', 'ความหลงใหลและความสนุก ใจดีเข้าไว้ ไม่ใช่แข่งกัน', 'ความทะเยอทะยานและความริเริ่มเปิดประตู ทำที่เริ่มให้จบ', 'การขยับที่กล้าต้องมีงบ หนุนประกาย ไม่ใช่ไฟป่า', 'ขยับ เหงื่อออก ระบาย แล้วพักอย่างตั้งใจ') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (34, 'queen-of-wands', 'minor', 'wands', 13, 'cards/wands-13') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (34, 'en', 'Queen of Wands', '["mastery within","nurturing command","trusted counsel","drive"]', '["smothering","inner drought","manipulation","burnout"]', 'Mastery turned inward: calm command, deep care, counsel others trust. Fire moves it: energy, courage, and momentum.', 'Care curdled: smothering, martyrdom, or counsel with hooks. Refill, then lead. Fire unchecked: haste, burnout, or pride running the show.', 'Passion and playfulness — keep it kind, not competitive.', 'Ambition and initiative open doors; finish what you start.', 'Bold moves need budgets; fund the spark, not the blaze.', 'Move, sweat, discharge — then rest deliberately.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (34, 'th', 'ราชินีไม้เท้า', '["ความชำนาญใน","การนำด้วยการดูแล","ที่ปรึกษาที่ไว้ใจ","แรงขับ"]', '["การประคบประหงม","ความแห้งใน","การบงการ","หมดไฟ"]', 'ความชำนาญหันเข้าใน การบัญชาอย่างสงบ การดูแลลึกๆ คำปรึกษาที่คนไว้ใจ ไฟขับเคลื่อนมัน พลังงาน ความกล้า และโมเมนตัม', 'การดูแลที่เสีย ประคบประหงมเกิน เป็นเหยื่อ หรือคำปรึกษาที่มีตะขอ เติมก่อน แล้วค่อยนำ ไฟที่ไม่ถูกคุม ความรีบร้อน หมดไฟ หรืออีโก้เป็นคนขับ', 'ความหลงใหลและความสนุก ใจดีเข้าไว้ ไม่ใช่แข่งกัน', 'ความทะเยอทะยานและความริเริ่มเปิดประตู ทำที่เริ่มให้จบ', 'การขยับที่กล้าต้องมีงบ หนุนประกาย ไม่ใช่ไฟป่า', 'ขยับ เหงื่อออก ระบาย แล้วพักอย่างตั้งใจ') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (35, 'king-of-wands', 'minor', 'wands', 14, 'cards/wands-14') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (35, 'en', 'King of Wands', '["mastery without","steady authority","legacy lead","drive"]', '["domineering","abdication","hollow crown","burnout"]', 'Mastery turned outward: steady authority, long view, leadership that lasts. Fire moves it: energy, courage, and momentum.', 'Authority warped: domineering, checked-out, or a crown with no kingdom. Re-earn it. Fire unchecked: haste, burnout, or pride running the show.', 'Passion and playfulness — keep it kind, not competitive.', 'Ambition and initiative open doors; finish what you start.', 'Bold moves need budgets; fund the spark, not the blaze.', 'Move, sweat, discharge — then rest deliberately.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (35, 'th', 'ราชาไม้เท้า', '["ความชำนาญนอก","อำนาจที่มั่นคง","การนำที่สืบต่อ","แรงขับ"]', '["การครอบงำ","การสละหน้าที่","มงกุฎที่กลวง","หมดไฟ"]', 'ความชำนาญหันออกนอก อำนาจที่มั่นคง มุมยาว การนำที่อยู่ยาว ไฟขับเคลื่อนมัน พลังงาน ความกล้า และโมเมนตัม', 'อำนาจที่บิด ครอบงำ ถอนตัว หรือมงกุฎที่ไม่มีอาณาจักร กลับไปทำให้สมใหม่ ไฟที่ไม่ถูกคุม ความรีบร้อน หมดไฟ หรืออีโก้เป็นคนขับ', 'ความหลงใหลและความสนุก ใจดีเข้าไว้ ไม่ใช่แข่งกัน', 'ความทะเยอทะยานและความริเริ่มเปิดประตู ทำที่เริ่มให้จบ', 'การขยับที่กล้าต้องมีงบ หนุนประกาย ไม่ใช่ไฟป่า', 'ขยับ เหงื่อออก ระบาย แล้วพักอย่างตั้งใจ') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (36, 'ace-of-cups', 'minor', 'cups', 1, 'cards/cups-01') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (36, 'en', 'Ace of Cups', '["seed","gift","pure potential","feelings"]', '["blocked seed","missed gift","hollow start","emotional fog"]', 'A new seed in this suit''s domain — raw, bright potential. Water carries it: feelings, intuition, and closeness.', 'The seed cannot sprout yet: wrong soil, wrong season, or a gift refused. Water stagnates: moodiness, clinging, or feelings running the meeting.', 'The heart of the matter — tenderness, honesty, flow.', 'Empathy and teamwork; watch emotional decisions.', 'Spend from values, not moods; let income flow, then hold some.', 'Feelings live in the body; hydrate, rest, name them.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (36, 'th', 'เอซ ถ้วย', '["เมล็ด","ของขวัญ","ศักยภาพบริสุทธิ์","ความรู้สึก"]', '["เมล็ดที่ติดขัด","ของขวัญที่พลาด","การเริ่มที่กลวง","หมอกอารมณ์"]', 'เมล็ดใหม่ในอาณาเขตของไพ่ชุดนี้ ศักยภาพดิบที่สดใส น้ำพามันไป ความรู้สึก สัญชาตญาณ และความใกล้ชิด', 'เมล็ดยังงอกไม่ได้ ดินผิด ฤดูผิด หรือของขวัญที่ถูกปฏิเสธ น้ำนิ่ง อารมณ์แปรปรวน การยึดติด หรือความรู้สึกเข้าประชุมแทน', 'หัวใจของเรื่อง ความอ่อนโยน ความซื่อสัตย์ กระแส', 'ความเข้าอกเข้าใจและทีมเวิร์ก ระวังตัดสินใจด้วยอารมณ์', 'ใช้ตามค่านิยม ไม่ใช่อารมณ์ ให้รายได้ไหล แล้วเก็บบ้าง', 'ความรู้สึกอยู่ในร่างกาย ดื่มน้ำ พัก ตั้งชื่อมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (37, 'two-of-cups', 'minor', 'cups', 2, 'cards/cups-02') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (37, 'en', 'Two of Cups', '["balance","partnership","first choice","feelings"]', '["imbalance","stalemate","avoided choice","emotional fog"]', 'Two forces meet: partnership, balance, or the first real choice. Water carries it: feelings, intuition, and closeness.', 'The pair is off-balance: stalemate, tension, or a choice dodged. Water stagnates: moodiness, clinging, or feelings running the meeting.', 'The heart of the matter — tenderness, honesty, flow.', 'Empathy and teamwork; watch emotional decisions.', 'Spend from values, not moods; let income flow, then hold some.', 'Feelings live in the body; hydrate, rest, name them.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (37, 'th', '2 ถ้วย', '["ความสมดุล","หุ้นส่วน","ทางเลือกแรก","ความรู้สึก"]', '["ความไม่สมดุล","การตัน","ทางเลือกที่เลี่ยง","หมอกอารมณ์"]', 'พลังสองสายมาบรรจบ หุ้นส่วน ความสมดุล หรือทางเลือกจริงครั้งแรก น้ำพามันไป ความรู้สึก สัญชาตญาณ และความใกล้ชิด', 'คู่นี้เสียสมดุล ตัน ตึง หรือทางเลือกที่ถูกเลี่ยง น้ำนิ่ง อารมณ์แปรปรวน การยึดติด หรือความรู้สึกเข้าประชุมแทน', 'หัวใจของเรื่อง ความอ่อนโยน ความซื่อสัตย์ กระแส', 'ความเข้าอกเข้าใจและทีมเวิร์ก ระวังตัดสินใจด้วยอารมณ์', 'ใช้ตามค่านิยม ไม่ใช่อารมณ์ ให้รายได้ไหล แล้วเก็บบ้าง', 'ความรู้สึกอยู่ในร่างกาย ดื่มน้ำ พัก ตั้งชื่อมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (38, 'three-of-cups', 'minor', 'cups', 3, 'cards/cups-03') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (38, 'en', 'Three of Cups', '["first fruits","togetherness","expression","feelings"]', '["scattered trio","gossip","delayed fruits","emotional fog"]', 'First fruits: growth shows, people gather, expression flows. Water carries it: feelings, intuition, and closeness.', 'The trio frays: miscommunication, gossip, or fruits that need more season. Water stagnates: moodiness, clinging, or feelings running the meeting.', 'The heart of the matter — tenderness, honesty, flow.', 'Empathy and teamwork; watch emotional decisions.', 'Spend from values, not moods; let income flow, then hold some.', 'Feelings live in the body; hydrate, rest, name them.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (38, 'th', '3 ถ้วย', '["ผลแรก","ความพร้อมหน้า","การแสดงออก","ความรู้สึก"]', '["สามคนที่แตก","นินทา","ผลที่ช้า","หมอกอารมณ์"]', 'ผลแรก ความเติบโตเริ่มเห็น คนรวมกัน การแสดงออกไหล น้ำพามันไป ความรู้สึก สัญชาตญาณ และความใกล้ชิด', 'สามคนเริ่มขาด การสื่อสารพลาด นินทา หรือผลที่ต้องรอฤดูอีกหน่อย น้ำนิ่ง อารมณ์แปรปรวน การยึดติด หรือความรู้สึกเข้าประชุมแทน', 'หัวใจของเรื่อง ความอ่อนโยน ความซื่อสัตย์ กระแส', 'ความเข้าอกเข้าใจและทีมเวิร์ก ระวังตัดสินใจด้วยอารมณ์', 'ใช้ตามค่านิยม ไม่ใช่อารมณ์ ให้รายได้ไหล แล้วเก็บบ้าง', 'ความรู้สึกอยู่ในร่างกาย ดื่มน้ำ พัก ตั้งชื่อมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (39, 'four-of-cups', 'minor', 'cups', 4, 'cards/cups-04') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (39, 'en', 'Four of Cups', '["rest","foundation","pause to hold","feelings"]', '["stagnation","rigid hold","rest refused","emotional fog"]', 'Four walls: rest, consolidate, hold what you built. Water carries it: feelings, intuition, and closeness.', 'Rest curdled into rut: clinging to the walls instead of living in the house. Water stagnates: moodiness, clinging, or feelings running the meeting.', 'The heart of the matter — tenderness, honesty, flow.', 'Empathy and teamwork; watch emotional decisions.', 'Spend from values, not moods; let income flow, then hold some.', 'Feelings live in the body; hydrate, rest, name them.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (39, 'th', '4 ถ้วย', '["การพัก","รากฐาน","การหยุดเพื่อรักษา","ความรู้สึก"]', '["การนิ่งตาย","การยึดแข็ง","การปฏิเสธการพัก","หมอกอารมณ์"]', 'กำแพงสี่ด้าน พัก ประสาน รักษาสิ่งที่สร้างมา น้ำพามันไป ความรู้สึก สัญชาตญาณ และความใกล้ชิด', 'การพักกลายเป็นร่อง ยึดกำแพงแทนที่จะอยู่ในบ้าน น้ำนิ่ง อารมณ์แปรปรวน การยึดติด หรือความรู้สึกเข้าประชุมแทน', 'หัวใจของเรื่อง ความอ่อนโยน ความซื่อสัตย์ กระแส', 'ความเข้าอกเข้าใจและทีมเวิร์ก ระวังตัดสินใจด้วยอารมณ์', 'ใช้ตามค่านิยม ไม่ใช่อารมณ์ ให้รายได้ไหล แล้วเก็บบ้าง', 'ความรู้สึกอยู่ในร่างกาย ดื่มน้ำ พัก ตั้งชื่อมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (40, 'five-of-cups', 'minor', 'cups', 5, 'cards/cups-05') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (40, 'en', 'Five of Cups', '["friction","loss felt","shake-up","feelings"]', '["longer conflict","blame","slow recovery","emotional fog"]', 'Friction with a lesson: loss, conflict, or a shake-up that reveals what stands. Water carries it: feelings, intuition, and closeness.', 'The fight drags on or blame spreads; recovery is slow but possible — stop feeding it. Water stagnates: moodiness, clinging, or feelings running the meeting.', 'The heart of the matter — tenderness, honesty, flow.', 'Empathy and teamwork; watch emotional decisions.', 'Spend from values, not moods; let income flow, then hold some.', 'Feelings live in the body; hydrate, rest, name them.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (40, 'th', '5 ถ้วย', '["แรงเสียดทาน","ความสูญเสียที่รู้สึก","แรงเขย่า","ความรู้สึก"]', '["ความขัดแย้งที่ยาว","การโทษ","การฟื้นช้า","หมอกอารมณ์"]', 'แรงเสียดทานพร้อมบทเรียน ความสูญเสีย ความขัดแย้ง หรือแรงเขย่าที่เผยให้เห็นสิ่งที่ยืนอยู่ น้ำพามันไป ความรู้สึก สัญชาตญาณ และความใกล้ชิด', 'การสู้ยืดเยื้อหรือการโทษกันลาม การฟื้นช้าแต่เป็นไปได้ เลิกให้อาหารมัน น้ำนิ่ง อารมณ์แปรปรวน การยึดติด หรือความรู้สึกเข้าประชุมแทน', 'หัวใจของเรื่อง ความอ่อนโยน ความซื่อสัตย์ กระแส', 'ความเข้าอกเข้าใจและทีมเวิร์ก ระวังตัดสินใจด้วยอารมณ์', 'ใช้ตามค่านิยม ไม่ใช่อารมณ์ ให้รายได้ไหล แล้วเก็บบ้าง', 'ความรู้สึกอยู่ในร่างกาย ดื่มน้ำ พัก ตั้งชื่อมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (41, 'six-of-cups', 'minor', 'cups', 6, 'cards/cups-06') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (41, 'en', 'Six of Cups', '["ease after strain","giving","nostalgia","feelings"]', '["strings attached","stuck past","unequal give","emotional fog"]', 'Breathing room: help given or received, sweetness from the past, smoother water. Water carries it: feelings, intuition, and closeness.', 'Giving with strings, or living in the rearview: accept help cleanly, visit the past — do not move back in. Water stagnates: moodiness, clinging, or feelings running the meeting.', 'The heart of the matter — tenderness, honesty, flow.', 'Empathy and teamwork; watch emotional decisions.', 'Spend from values, not moods; let income flow, then hold some.', 'Feelings live in the body; hydrate, rest, name them.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (41, 'th', '6 ถ้วย', '["ความโล่งหลังเหนื่อย","การให้","ความคิดถึง","ความรู้สึก"]', '["เงื่อนไขที่ผูก","อดีตที่ติด","การให้ที่ไม่เท่า","หมอกอารมณ์"]', 'ที่หายใจ ความช่วยเหลือที่ให้หรือรับ ความหวานจากอดีต น้ำที่เรียบขึ้น น้ำพามันไป ความรู้สึก สัญชาตญาณ และความใกล้ชิด', 'ให้แบบมีเงื่อนไข หรืออยู่ในกระจกมองหลัง รับความช่วยเหลืออย่างสะอาด แวะอดีต อย่าย้ายกลับเข้าไป น้ำนิ่ง อารมณ์แปรปรวน การยึดติด หรือความรู้สึกเข้าประชุมแทน', 'หัวใจของเรื่อง ความอ่อนโยน ความซื่อสัตย์ กระแส', 'ความเข้าอกเข้าใจและทีมเวิร์ก ระวังตัดสินใจด้วยอารมณ์', 'ใช้ตามค่านิยม ไม่ใช่อารมณ์ ให้รายได้ไหล แล้วเก็บบ้าง', 'ความรู้สึกอยู่ในร่างกาย ดื่มน้ำ พัก ตั้งชื่อมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (42, 'seven-of-cups', 'minor', 'cups', 7, 'cards/cups-07') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (42, 'en', 'Seven of Cups', '["assessment","many options","stand your ground","feelings"]', '["overwhelm","illusion of choice","defensive crouch","emotional fog"]', 'Step back and assess: many options, one position to defend, patience before the next move. Water carries it: feelings, intuition, and closeness.', 'Too many threads or a defensive crouch: narrow the field, then stand — or strategically yield. Water stagnates: moodiness, clinging, or feelings running the meeting.', 'The heart of the matter — tenderness, honesty, flow.', 'Empathy and teamwork; watch emotional decisions.', 'Spend from values, not moods; let income flow, then hold some.', 'Feelings live in the body; hydrate, rest, name them.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (42, 'th', '7 ถ้วย', '["การประเมิน","ทางเลือกมาก","รักษาที่ยืน","ความรู้สึก"]', '["ความท่วมท้น","ภาพลวงของทางเลือก","ท่าตั้งรับ","หมอกอารมณ์"]', 'ถอยมาประเมิน ทางเลือกมาก ที่ยืนที่ต้องรักษา อดทนก่อนขยับต่อไป น้ำพามันไป ความรู้สึก สัญชาตญาณ และความใกล้ชิด', 'ด้ายมากเกินไปหรือท่าตั้งรับ แคบสนามลง แล้วค่อยยืน หรือถอยอย่างมีกลยุทธ์ น้ำนิ่ง อารมณ์แปรปรวน การยึดติด หรือความรู้สึกเข้าประชุมแทน', 'หัวใจของเรื่อง ความอ่อนโยน ความซื่อสัตย์ กระแส', 'ความเข้าอกเข้าใจและทีมเวิร์ก ระวังตัดสินใจด้วยอารมณ์', 'ใช้ตามค่านิยม ไม่ใช่อารมณ์ ให้รายได้ไหล แล้วเก็บบ้าง', 'ความรู้สึกอยู่ในร่างกาย ดื่มน้ำ พัก ตั้งชื่อมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (43, 'eight-of-cups', 'minor', 'cups', 8, 'cards/cups-08') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (43, 'en', 'Eight of Cups', '["mastery in motion","focused work","swift change","feelings"]', '["scattered effort","perfectionism","too fast","emotional fog"]', 'Skilled motion: focused work compounds, or change arrives fast — meet it prepared. Water carries it: feelings, intuition, and closeness.', 'Effort scattered or perfectionism stalling the line; slow one thing down to speed the whole up. Water stagnates: moodiness, clinging, or feelings running the meeting.', 'The heart of the matter — tenderness, honesty, flow.', 'Empathy and teamwork; watch emotional decisions.', 'Spend from values, not moods; let income flow, then hold some.', 'Feelings live in the body; hydrate, rest, name them.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (43, 'th', '8 ถ้วย', '["ความชำนาญที่เคลื่อน","งานโฟกัส","การเปลี่ยนที่เร็ว","ความรู้สึก"]', '["ความพยายามที่แตก","ความสมบูรณ์แบบ","เร็วเกินไป","หมอกอารมณ์"]', 'การเคลื่อนอย่างชำนาญ งานโฟกัสทบต้น หรือการเปลี่ยนมาเร็ว เจอมันอย่างเตรียมพร้อม น้ำพามันไป ความรู้สึก สัญชาตญาณ และความใกล้ชิด', 'ความพยายามกระจัดกระจายหรือความสมบูรณ์แบบทำให้สายพานหยุด ชะลอสิ่งหนึ่งเพื่อให้ทั้งหมดเร็วขึ้น น้ำนิ่ง อารมณ์แปรปรวน การยึดติด หรือความรู้สึกเข้าประชุมแทน', 'หัวใจของเรื่อง ความอ่อนโยน ความซื่อสัตย์ กระแส', 'ความเข้าอกเข้าใจและทีมเวิร์ก ระวังตัดสินใจด้วยอารมณ์', 'ใช้ตามค่านิยม ไม่ใช่อารมณ์ ให้รายได้ไหล แล้วเก็บบ้าง', 'ความรู้สึกอยู่ในร่างกาย ดื่มน้ำ พัก ตั้งชื่อมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (44, 'nine-of-cups', 'minor', 'cups', 9, 'cards/cups-09') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (44, 'en', 'Nine of Cups', '["near-complete","wishes","resilience","feelings"]', '["nearly-but-stuck","anxiety nights","walled garden","emotional fog"]', 'Almost whole: wishes close, resilience proven — guard the last stretch with care. Water carries it: feelings, intuition, and closeness.', 'So close yet stuck: worry loops or a comfort zone fenced too high. Name the fear, take the final step. Water stagnates: moodiness, clinging, or feelings running the meeting.', 'The heart of the matter — tenderness, honesty, flow.', 'Empathy and teamwork; watch emotional decisions.', 'Spend from values, not moods; let income flow, then hold some.', 'Feelings live in the body; hydrate, rest, name them.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (44, 'th', '9 ถ้วย', '["เกือบสมบูรณ์","ความปรารถนา","ความอึด","ความรู้สึก"]', '["เกือบแต่ติด","คืนที่นอนไม่หลับ","สวนที่มีกำแพง","หมอกอารมณ์"]', 'เกือบครบ ความปรารถนาใกล้ ความอึดพิสูจน์แล้ว ประคองช่วงสุดท้ายดีๆ น้ำพามันไป ความรู้สึก สัญชาตญาณ และความใกล้ชิด', 'ใกล้แต่ติด วงจรความกังวลหรือเขตสบายที่รั้วสูงไป ตั้งชื่อความกลัว แล้วก้าวสุดท้าย น้ำนิ่ง อารมณ์แปรปรวน การยึดติด หรือความรู้สึกเข้าประชุมแทน', 'หัวใจของเรื่อง ความอ่อนโยน ความซื่อสัตย์ กระแส', 'ความเข้าอกเข้าใจและทีมเวิร์ก ระวังตัดสินใจด้วยอารมณ์', 'ใช้ตามค่านิยม ไม่ใช่อารมณ์ ให้รายได้ไหล แล้วเก็บบ้าง', 'ความรู้สึกอยู่ในร่างกาย ดื่มน้ำ พัก ตั้งชื่อมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (45, 'ten-of-cups', 'minor', 'cups', 10, 'cards/cups-10') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (45, 'en', 'Ten of Cups', '["completion","full circle","legacy","feelings"]', '["overfull","crashing end","burden shared badly","emotional fog"]', 'The full arc of the suit: completion, culmination, what carries forward. Water carries it: feelings, intuition, and closeness.', 'Overfull or ending hard: too much carried, or a cycle closing messily — set down, sort out, close clean. Water stagnates: moodiness, clinging, or feelings running the meeting.', 'The heart of the matter — tenderness, honesty, flow.', 'Empathy and teamwork; watch emotional decisions.', 'Spend from values, not moods; let income flow, then hold some.', 'Feelings live in the body; hydrate, rest, name them.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (45, 'th', '10 ถ้วย', '["ความสมบูรณ์","วงเต็ม","มรดก","ความรู้สึก"]', '["ล้นเกิน","จุดจบที่กระแทก","ภาระที่แบ่งไม่ดี","หมอกอารมณ์"]', 'ส่วนโค้งเต็มของไพ่ชุดนี้ ความสมบูรณ์ จุดสูงสุด สิ่งที่ส่งต่อ น้ำพามันไป ความรู้สึก สัญชาตญาณ และความใกล้ชิด', 'ล้นหรือจบแบบกระแทก แบกมากเกิน หรือวัฏจักรปิดแบบเละ วางลง จัดการ ปิดให้สะอาด น้ำนิ่ง อารมณ์แปรปรวน การยึดติด หรือความรู้สึกเข้าประชุมแทน', 'หัวใจของเรื่อง ความอ่อนโยน ความซื่อสัตย์ กระแส', 'ความเข้าอกเข้าใจและทีมเวิร์ก ระวังตัดสินใจด้วยอารมณ์', 'ใช้ตามค่านิยม ไม่ใช่อารมณ์ ให้รายได้ไหล แล้วเก็บบ้าง', 'ความรู้สึกอยู่ในร่างกาย ดื่มน้ำ พัก ตั้งชื่อมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (46, 'page-of-cups', 'minor', 'cups', 11, 'cards/cups-11') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (46, 'en', 'Page of Cups', '["student","message","fresh curiosity","feelings"]', '["gossip","distraction","study skipped","emotional fog"]', 'The eager student: a message, a new study, curiosity first — beginner''s mind, open notebook. Water carries it: feelings, intuition, and closeness.', 'Distracted student: gossip over study, shiny hopping. Pick one page and actually read it. Water stagnates: moodiness, clinging, or feelings running the meeting.', 'The heart of the matter — tenderness, honesty, flow.', 'Empathy and teamwork; watch emotional decisions.', 'Spend from values, not moods; let income flow, then hold some.', 'Feelings live in the body; hydrate, rest, name them.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (46, 'th', 'เพจถ้วย', '["นักเรียน","ข้อความ","ความอยากรู้สดๆ","ความรู้สึก"]', '["นินทา","สิ่งรบกวน","การเรียนที่ข้าม","หมอกอารมณ์"]', 'นักเรียนที่กระตือรือร้น ข้อความ การเรียนใหม่ ความอยากรู้ก่อน ใจแบบมือใหม่ สมุดที่เปิด น้ำพามันไป ความรู้สึก สัญชาตญาณ และความใกล้ชิด', 'นักเรียนที่วอกแวก นินทาแทนเรียน กระโดดหาของแวววาว เลือกมาสักหน้าแล้วอ่านจริง น้ำนิ่ง อารมณ์แปรปรวน การยึดติด หรือความรู้สึกเข้าประชุมแทน', 'หัวใจของเรื่อง ความอ่อนโยน ความซื่อสัตย์ กระแส', 'ความเข้าอกเข้าใจและทีมเวิร์ก ระวังตัดสินใจด้วยอารมณ์', 'ใช้ตามค่านิยม ไม่ใช่อารมณ์ ให้รายได้ไหล แล้วเก็บบ้าง', 'ความรู้สึกอยู่ในร่างกาย ดื่มน้ำ พัก ตั้งชื่อมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (47, 'knight-of-cups', 'minor', 'cups', 12, 'cards/cups-12') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (47, 'en', 'Knight of Cups', '["charge","quest","momentum","feelings"]', '["reckless charge","hot-cold","quest drift","emotional fog"]', 'The charger: full momentum toward the quest — brave, fast, all-in. Water carries it: feelings, intuition, and closeness.', 'Charging past the target or blowing hot and cold: rein in, re-aim, then ride. Water stagnates: moodiness, clinging, or feelings running the meeting.', 'The heart of the matter — tenderness, honesty, flow.', 'Empathy and teamwork; watch emotional decisions.', 'Spend from values, not moods; let income flow, then hold some.', 'Feelings live in the body; hydrate, rest, name them.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (47, 'th', 'อัศวินถ้วย', '["การพุ่ง","ภารกิจ","โมเมนตัม","ความรู้สึก"]', '["การพุ่งที่ประมาท","ร้อนหนาว","ภารกิจที่ลอย","หมอกอารมณ์"]', 'ผู้พุ่งทะยาน โมเมนตัมเต็มสู่ภารกิจ กล้า เร็ว ทุ่มหมด น้ำพามันไป ความรู้สึก สัญชาตญาณ และความใกล้ชิด', 'พุ่งเลยเป้าหรือร้อนๆ หนาวๆ ดึงบังเหียน เล็งใหม่ แล้วค่อยขี่ น้ำนิ่ง อารมณ์แปรปรวน การยึดติด หรือความรู้สึกเข้าประชุมแทน', 'หัวใจของเรื่อง ความอ่อนโยน ความซื่อสัตย์ กระแส', 'ความเข้าอกเข้าใจและทีมเวิร์ก ระวังตัดสินใจด้วยอารมณ์', 'ใช้ตามค่านิยม ไม่ใช่อารมณ์ ให้รายได้ไหล แล้วเก็บบ้าง', 'ความรู้สึกอยู่ในร่างกาย ดื่มน้ำ พัก ตั้งชื่อมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (48, 'queen-of-cups', 'minor', 'cups', 13, 'cards/cups-13') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (48, 'en', 'Queen of Cups', '["mastery within","nurturing command","trusted counsel","feelings"]', '["smothering","inner drought","manipulation","emotional fog"]', 'Mastery turned inward: calm command, deep care, counsel others trust. Water carries it: feelings, intuition, and closeness.', 'Care curdled: smothering, martyrdom, or counsel with hooks. Refill, then lead. Water stagnates: moodiness, clinging, or feelings running the meeting.', 'The heart of the matter — tenderness, honesty, flow.', 'Empathy and teamwork; watch emotional decisions.', 'Spend from values, not moods; let income flow, then hold some.', 'Feelings live in the body; hydrate, rest, name them.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (48, 'th', 'ราชินีถ้วย', '["ความชำนาญใน","การนำด้วยการดูแล","ที่ปรึกษาที่ไว้ใจ","ความรู้สึก"]', '["การประคบประหงม","ความแห้งใน","การบงการ","หมอกอารมณ์"]', 'ความชำนาญหันเข้าใน การบัญชาอย่างสงบ การดูแลลึกๆ คำปรึกษาที่คนไว้ใจ น้ำพามันไป ความรู้สึก สัญชาตญาณ และความใกล้ชิด', 'การดูแลที่เสีย ประคบประหงมเกิน เป็นเหยื่อ หรือคำปรึกษาที่มีตะขอ เติมก่อน แล้วค่อยนำ น้ำนิ่ง อารมณ์แปรปรวน การยึดติด หรือความรู้สึกเข้าประชุมแทน', 'หัวใจของเรื่อง ความอ่อนโยน ความซื่อสัตย์ กระแส', 'ความเข้าอกเข้าใจและทีมเวิร์ก ระวังตัดสินใจด้วยอารมณ์', 'ใช้ตามค่านิยม ไม่ใช่อารมณ์ ให้รายได้ไหล แล้วเก็บบ้าง', 'ความรู้สึกอยู่ในร่างกาย ดื่มน้ำ พัก ตั้งชื่อมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (49, 'king-of-cups', 'minor', 'cups', 14, 'cards/cups-14') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (49, 'en', 'King of Cups', '["mastery without","steady authority","legacy lead","feelings"]', '["domineering","abdication","hollow crown","emotional fog"]', 'Mastery turned outward: steady authority, long view, leadership that lasts. Water carries it: feelings, intuition, and closeness.', 'Authority warped: domineering, checked-out, or a crown with no kingdom. Re-earn it. Water stagnates: moodiness, clinging, or feelings running the meeting.', 'The heart of the matter — tenderness, honesty, flow.', 'Empathy and teamwork; watch emotional decisions.', 'Spend from values, not moods; let income flow, then hold some.', 'Feelings live in the body; hydrate, rest, name them.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (49, 'th', 'ราชาถ้วย', '["ความชำนาญนอก","อำนาจที่มั่นคง","การนำที่สืบต่อ","ความรู้สึก"]', '["การครอบงำ","การสละหน้าที่","มงกุฎที่กลวง","หมอกอารมณ์"]', 'ความชำนาญหันออกนอก อำนาจที่มั่นคง มุมยาว การนำที่อยู่ยาว น้ำพามันไป ความรู้สึก สัญชาตญาณ และความใกล้ชิด', 'อำนาจที่บิด ครอบงำ ถอนตัว หรือมงกุฎที่ไม่มีอาณาจักร กลับไปทำให้สมใหม่ น้ำนิ่ง อารมณ์แปรปรวน การยึดติด หรือความรู้สึกเข้าประชุมแทน', 'หัวใจของเรื่อง ความอ่อนโยน ความซื่อสัตย์ กระแส', 'ความเข้าอกเข้าใจและทีมเวิร์ก ระวังตัดสินใจด้วยอารมณ์', 'ใช้ตามค่านิยม ไม่ใช่อารมณ์ ให้รายได้ไหล แล้วเก็บบ้าง', 'ความรู้สึกอยู่ในร่างกาย ดื่มน้ำ พัก ตั้งชื่อมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (50, 'ace-of-swords', 'minor', 'swords', 1, 'cards/swords-01') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (50, 'en', 'Ace of Swords', '["seed","gift","pure potential","mind"]', '["blocked seed","missed gift","hollow start","overthinking"]', 'A new seed in this suit''s domain — raw, bright potential. Air cuts through: thought, truth, and clear words.', 'The seed cannot sprout yet: wrong soil, wrong season, or a gift refused. Air turned blade inward: overthinking, harsh self-talk, or words you cannot unsay.', 'Say the true thing kindly; clarity is kindness here.', 'Analysis, contracts, strategy — think it through fully.', 'Decide with numbers, not nerves; cut one cost.', 'Quiet the mind: sleep, less input, one worry at a time.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (50, 'th', 'เอซ ดาบ', '["เมล็ด","ของขวัญ","ศักยภาพบริสุทธิ์","ความคิด"]', '["เมล็ดที่ติดขัด","ของขวัญที่พลาด","การเริ่มที่กลวง","คิดมาก"]', 'เมล็ดใหม่ในอาณาเขตของไพ่ชุดนี้ ศักยภาพดิบที่สดใส อากาศตัดผ่าน ความคิด ความจริง และคำพูดที่ชัด', 'เมล็ดยังงอกไม่ได้ ดินผิด ฤดูผิด หรือของขวัญที่ถูกปฏิเสธ อากาศกลายเป็นใบมีดหันเข้าใน คิดมาก พูดกับตัวเองแรงๆ หรือคำพูดที่เรียกคืนไม่ได้', 'พูดความจริงอย่างอ่อนโยน ความชัดคือความใจดีตรงนี้', 'วิเคราะห์ สัญญา กลยุทธ์ คิดให้ครบ', 'ตัดสินใจด้วยตัวเลข ไม่ใช่ประสาท ตัดค่าใช้จ่ายสักอย่าง', 'ทำหัวให้เงียบ นอน รับข้อมูลน้อยลง กังวลทีละเรื่อง') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (51, 'two-of-swords', 'minor', 'swords', 2, 'cards/swords-02') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (51, 'en', 'Two of Swords', '["balance","partnership","first choice","mind"]', '["imbalance","stalemate","avoided choice","overthinking"]', 'Two forces meet: partnership, balance, or the first real choice. Air cuts through: thought, truth, and clear words.', 'The pair is off-balance: stalemate, tension, or a choice dodged. Air turned blade inward: overthinking, harsh self-talk, or words you cannot unsay.', 'Say the true thing kindly; clarity is kindness here.', 'Analysis, contracts, strategy — think it through fully.', 'Decide with numbers, not nerves; cut one cost.', 'Quiet the mind: sleep, less input, one worry at a time.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (51, 'th', '2 ดาบ', '["ความสมดุล","หุ้นส่วน","ทางเลือกแรก","ความคิด"]', '["ความไม่สมดุล","การตัน","ทางเลือกที่เลี่ยง","คิดมาก"]', 'พลังสองสายมาบรรจบ หุ้นส่วน ความสมดุล หรือทางเลือกจริงครั้งแรก อากาศตัดผ่าน ความคิด ความจริง และคำพูดที่ชัด', 'คู่นี้เสียสมดุล ตัน ตึง หรือทางเลือกที่ถูกเลี่ยง อากาศกลายเป็นใบมีดหันเข้าใน คิดมาก พูดกับตัวเองแรงๆ หรือคำพูดที่เรียกคืนไม่ได้', 'พูดความจริงอย่างอ่อนโยน ความชัดคือความใจดีตรงนี้', 'วิเคราะห์ สัญญา กลยุทธ์ คิดให้ครบ', 'ตัดสินใจด้วยตัวเลข ไม่ใช่ประสาท ตัดค่าใช้จ่ายสักอย่าง', 'ทำหัวให้เงียบ นอน รับข้อมูลน้อยลง กังวลทีละเรื่อง') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (52, 'three-of-swords', 'minor', 'swords', 3, 'cards/swords-03') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (52, 'en', 'Three of Swords', '["first fruits","togetherness","expression","mind"]', '["scattered trio","gossip","delayed fruits","overthinking"]', 'First fruits: growth shows, people gather, expression flows. Air cuts through: thought, truth, and clear words.', 'The trio frays: miscommunication, gossip, or fruits that need more season. Air turned blade inward: overthinking, harsh self-talk, or words you cannot unsay.', 'Say the true thing kindly; clarity is kindness here.', 'Analysis, contracts, strategy — think it through fully.', 'Decide with numbers, not nerves; cut one cost.', 'Quiet the mind: sleep, less input, one worry at a time.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (52, 'th', '3 ดาบ', '["ผลแรก","ความพร้อมหน้า","การแสดงออก","ความคิด"]', '["สามคนที่แตก","นินทา","ผลที่ช้า","คิดมาก"]', 'ผลแรก ความเติบโตเริ่มเห็น คนรวมกัน การแสดงออกไหล อากาศตัดผ่าน ความคิด ความจริง และคำพูดที่ชัด', 'สามคนเริ่มขาด การสื่อสารพลาด นินทา หรือผลที่ต้องรอฤดูอีกหน่อย อากาศกลายเป็นใบมีดหันเข้าใน คิดมาก พูดกับตัวเองแรงๆ หรือคำพูดที่เรียกคืนไม่ได้', 'พูดความจริงอย่างอ่อนโยน ความชัดคือความใจดีตรงนี้', 'วิเคราะห์ สัญญา กลยุทธ์ คิดให้ครบ', 'ตัดสินใจด้วยตัวเลข ไม่ใช่ประสาท ตัดค่าใช้จ่ายสักอย่าง', 'ทำหัวให้เงียบ นอน รับข้อมูลน้อยลง กังวลทีละเรื่อง') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (53, 'four-of-swords', 'minor', 'swords', 4, 'cards/swords-04') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (53, 'en', 'Four of Swords', '["rest","foundation","pause to hold","mind"]', '["stagnation","rigid hold","rest refused","overthinking"]', 'Four walls: rest, consolidate, hold what you built. Air cuts through: thought, truth, and clear words.', 'Rest curdled into rut: clinging to the walls instead of living in the house. Air turned blade inward: overthinking, harsh self-talk, or words you cannot unsay.', 'Say the true thing kindly; clarity is kindness here.', 'Analysis, contracts, strategy — think it through fully.', 'Decide with numbers, not nerves; cut one cost.', 'Quiet the mind: sleep, less input, one worry at a time.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (53, 'th', '4 ดาบ', '["การพัก","รากฐาน","การหยุดเพื่อรักษา","ความคิด"]', '["การนิ่งตาย","การยึดแข็ง","การปฏิเสธการพัก","คิดมาก"]', 'กำแพงสี่ด้าน พัก ประสาน รักษาสิ่งที่สร้างมา อากาศตัดผ่าน ความคิด ความจริง และคำพูดที่ชัด', 'การพักกลายเป็นร่อง ยึดกำแพงแทนที่จะอยู่ในบ้าน อากาศกลายเป็นใบมีดหันเข้าใน คิดมาก พูดกับตัวเองแรงๆ หรือคำพูดที่เรียกคืนไม่ได้', 'พูดความจริงอย่างอ่อนโยน ความชัดคือความใจดีตรงนี้', 'วิเคราะห์ สัญญา กลยุทธ์ คิดให้ครบ', 'ตัดสินใจด้วยตัวเลข ไม่ใช่ประสาท ตัดค่าใช้จ่ายสักอย่าง', 'ทำหัวให้เงียบ นอน รับข้อมูลน้อยลง กังวลทีละเรื่อง') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (54, 'five-of-swords', 'minor', 'swords', 5, 'cards/swords-05') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (54, 'en', 'Five of Swords', '["friction","loss felt","shake-up","mind"]', '["longer conflict","blame","slow recovery","overthinking"]', 'Friction with a lesson: loss, conflict, or a shake-up that reveals what stands. Air cuts through: thought, truth, and clear words.', 'The fight drags on or blame spreads; recovery is slow but possible — stop feeding it. Air turned blade inward: overthinking, harsh self-talk, or words you cannot unsay.', 'Say the true thing kindly; clarity is kindness here.', 'Analysis, contracts, strategy — think it through fully.', 'Decide with numbers, not nerves; cut one cost.', 'Quiet the mind: sleep, less input, one worry at a time.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (54, 'th', '5 ดาบ', '["แรงเสียดทาน","ความสูญเสียที่รู้สึก","แรงเขย่า","ความคิด"]', '["ความขัดแย้งที่ยาว","การโทษ","การฟื้นช้า","คิดมาก"]', 'แรงเสียดทานพร้อมบทเรียน ความสูญเสีย ความขัดแย้ง หรือแรงเขย่าที่เผยให้เห็นสิ่งที่ยืนอยู่ อากาศตัดผ่าน ความคิด ความจริง และคำพูดที่ชัด', 'การสู้ยืดเยื้อหรือการโทษกันลาม การฟื้นช้าแต่เป็นไปได้ เลิกให้อาหารมัน อากาศกลายเป็นใบมีดหันเข้าใน คิดมาก พูดกับตัวเองแรงๆ หรือคำพูดที่เรียกคืนไม่ได้', 'พูดความจริงอย่างอ่อนโยน ความชัดคือความใจดีตรงนี้', 'วิเคราะห์ สัญญา กลยุทธ์ คิดให้ครบ', 'ตัดสินใจด้วยตัวเลข ไม่ใช่ประสาท ตัดค่าใช้จ่ายสักอย่าง', 'ทำหัวให้เงียบ นอน รับข้อมูลน้อยลง กังวลทีละเรื่อง') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (55, 'six-of-swords', 'minor', 'swords', 6, 'cards/swords-06') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (55, 'en', 'Six of Swords', '["ease after strain","giving","nostalgia","mind"]', '["strings attached","stuck past","unequal give","overthinking"]', 'Breathing room: help given or received, sweetness from the past, smoother water. Air cuts through: thought, truth, and clear words.', 'Giving with strings, or living in the rearview: accept help cleanly, visit the past — do not move back in. Air turned blade inward: overthinking, harsh self-talk, or words you cannot unsay.', 'Say the true thing kindly; clarity is kindness here.', 'Analysis, contracts, strategy — think it through fully.', 'Decide with numbers, not nerves; cut one cost.', 'Quiet the mind: sleep, less input, one worry at a time.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (55, 'th', '6 ดาบ', '["ความโล่งหลังเหนื่อย","การให้","ความคิดถึง","ความคิด"]', '["เงื่อนไขที่ผูก","อดีตที่ติด","การให้ที่ไม่เท่า","คิดมาก"]', 'ที่หายใจ ความช่วยเหลือที่ให้หรือรับ ความหวานจากอดีต น้ำที่เรียบขึ้น อากาศตัดผ่าน ความคิด ความจริง และคำพูดที่ชัด', 'ให้แบบมีเงื่อนไข หรืออยู่ในกระจกมองหลัง รับความช่วยเหลืออย่างสะอาด แวะอดีต อย่าย้ายกลับเข้าไป อากาศกลายเป็นใบมีดหันเข้าใน คิดมาก พูดกับตัวเองแรงๆ หรือคำพูดที่เรียกคืนไม่ได้', 'พูดความจริงอย่างอ่อนโยน ความชัดคือความใจดีตรงนี้', 'วิเคราะห์ สัญญา กลยุทธ์ คิดให้ครบ', 'ตัดสินใจด้วยตัวเลข ไม่ใช่ประสาท ตัดค่าใช้จ่ายสักอย่าง', 'ทำหัวให้เงียบ นอน รับข้อมูลน้อยลง กังวลทีละเรื่อง') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (56, 'seven-of-swords', 'minor', 'swords', 7, 'cards/swords-07') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (56, 'en', 'Seven of Swords', '["assessment","many options","stand your ground","mind"]', '["overwhelm","illusion of choice","defensive crouch","overthinking"]', 'Step back and assess: many options, one position to defend, patience before the next move. Air cuts through: thought, truth, and clear words.', 'Too many threads or a defensive crouch: narrow the field, then stand — or strategically yield. Air turned blade inward: overthinking, harsh self-talk, or words you cannot unsay.', 'Say the true thing kindly; clarity is kindness here.', 'Analysis, contracts, strategy — think it through fully.', 'Decide with numbers, not nerves; cut one cost.', 'Quiet the mind: sleep, less input, one worry at a time.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (56, 'th', '7 ดาบ', '["การประเมิน","ทางเลือกมาก","รักษาที่ยืน","ความคิด"]', '["ความท่วมท้น","ภาพลวงของทางเลือก","ท่าตั้งรับ","คิดมาก"]', 'ถอยมาประเมิน ทางเลือกมาก ที่ยืนที่ต้องรักษา อดทนก่อนขยับต่อไป อากาศตัดผ่าน ความคิด ความจริง และคำพูดที่ชัด', 'ด้ายมากเกินไปหรือท่าตั้งรับ แคบสนามลง แล้วค่อยยืน หรือถอยอย่างมีกลยุทธ์ อากาศกลายเป็นใบมีดหันเข้าใน คิดมาก พูดกับตัวเองแรงๆ หรือคำพูดที่เรียกคืนไม่ได้', 'พูดความจริงอย่างอ่อนโยน ความชัดคือความใจดีตรงนี้', 'วิเคราะห์ สัญญา กลยุทธ์ คิดให้ครบ', 'ตัดสินใจด้วยตัวเลข ไม่ใช่ประสาท ตัดค่าใช้จ่ายสักอย่าง', 'ทำหัวให้เงียบ นอน รับข้อมูลน้อยลง กังวลทีละเรื่อง') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (57, 'eight-of-swords', 'minor', 'swords', 8, 'cards/swords-08') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (57, 'en', 'Eight of Swords', '["mastery in motion","focused work","swift change","mind"]', '["scattered effort","perfectionism","too fast","overthinking"]', 'Skilled motion: focused work compounds, or change arrives fast — meet it prepared. Air cuts through: thought, truth, and clear words.', 'Effort scattered or perfectionism stalling the line; slow one thing down to speed the whole up. Air turned blade inward: overthinking, harsh self-talk, or words you cannot unsay.', 'Say the true thing kindly; clarity is kindness here.', 'Analysis, contracts, strategy — think it through fully.', 'Decide with numbers, not nerves; cut one cost.', 'Quiet the mind: sleep, less input, one worry at a time.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (57, 'th', '8 ดาบ', '["ความชำนาญที่เคลื่อน","งานโฟกัส","การเปลี่ยนที่เร็ว","ความคิด"]', '["ความพยายามที่แตก","ความสมบูรณ์แบบ","เร็วเกินไป","คิดมาก"]', 'การเคลื่อนอย่างชำนาญ งานโฟกัสทบต้น หรือการเปลี่ยนมาเร็ว เจอมันอย่างเตรียมพร้อม อากาศตัดผ่าน ความคิด ความจริง และคำพูดที่ชัด', 'ความพยายามกระจัดกระจายหรือความสมบูรณ์แบบทำให้สายพานหยุด ชะลอสิ่งหนึ่งเพื่อให้ทั้งหมดเร็วขึ้น อากาศกลายเป็นใบมีดหันเข้าใน คิดมาก พูดกับตัวเองแรงๆ หรือคำพูดที่เรียกคืนไม่ได้', 'พูดความจริงอย่างอ่อนโยน ความชัดคือความใจดีตรงนี้', 'วิเคราะห์ สัญญา กลยุทธ์ คิดให้ครบ', 'ตัดสินใจด้วยตัวเลข ไม่ใช่ประสาท ตัดค่าใช้จ่ายสักอย่าง', 'ทำหัวให้เงียบ นอน รับข้อมูลน้อยลง กังวลทีละเรื่อง') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (58, 'nine-of-swords', 'minor', 'swords', 9, 'cards/swords-09') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (58, 'en', 'Nine of Swords', '["near-complete","wishes","resilience","mind"]', '["nearly-but-stuck","anxiety nights","walled garden","overthinking"]', 'Almost whole: wishes close, resilience proven — guard the last stretch with care. Air cuts through: thought, truth, and clear words.', 'So close yet stuck: worry loops or a comfort zone fenced too high. Name the fear, take the final step. Air turned blade inward: overthinking, harsh self-talk, or words you cannot unsay.', 'Say the true thing kindly; clarity is kindness here.', 'Analysis, contracts, strategy — think it through fully.', 'Decide with numbers, not nerves; cut one cost.', 'Quiet the mind: sleep, less input, one worry at a time.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (58, 'th', '9 ดาบ', '["เกือบสมบูรณ์","ความปรารถนา","ความอึด","ความคิด"]', '["เกือบแต่ติด","คืนที่นอนไม่หลับ","สวนที่มีกำแพง","คิดมาก"]', 'เกือบครบ ความปรารถนาใกล้ ความอึดพิสูจน์แล้ว ประคองช่วงสุดท้ายดีๆ อากาศตัดผ่าน ความคิด ความจริง และคำพูดที่ชัด', 'ใกล้แต่ติด วงจรความกังวลหรือเขตสบายที่รั้วสูงไป ตั้งชื่อความกลัว แล้วก้าวสุดท้าย อากาศกลายเป็นใบมีดหันเข้าใน คิดมาก พูดกับตัวเองแรงๆ หรือคำพูดที่เรียกคืนไม่ได้', 'พูดความจริงอย่างอ่อนโยน ความชัดคือความใจดีตรงนี้', 'วิเคราะห์ สัญญา กลยุทธ์ คิดให้ครบ', 'ตัดสินใจด้วยตัวเลข ไม่ใช่ประสาท ตัดค่าใช้จ่ายสักอย่าง', 'ทำหัวให้เงียบ นอน รับข้อมูลน้อยลง กังวลทีละเรื่อง') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (59, 'ten-of-swords', 'minor', 'swords', 10, 'cards/swords-10') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (59, 'en', 'Ten of Swords', '["completion","full circle","legacy","mind"]', '["overfull","crashing end","burden shared badly","overthinking"]', 'The full arc of the suit: completion, culmination, what carries forward. Air cuts through: thought, truth, and clear words.', 'Overfull or ending hard: too much carried, or a cycle closing messily — set down, sort out, close clean. Air turned blade inward: overthinking, harsh self-talk, or words you cannot unsay.', 'Say the true thing kindly; clarity is kindness here.', 'Analysis, contracts, strategy — think it through fully.', 'Decide with numbers, not nerves; cut one cost.', 'Quiet the mind: sleep, less input, one worry at a time.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (59, 'th', '10 ดาบ', '["ความสมบูรณ์","วงเต็ม","มรดก","ความคิด"]', '["ล้นเกิน","จุดจบที่กระแทก","ภาระที่แบ่งไม่ดี","คิดมาก"]', 'ส่วนโค้งเต็มของไพ่ชุดนี้ ความสมบูรณ์ จุดสูงสุด สิ่งที่ส่งต่อ อากาศตัดผ่าน ความคิด ความจริง และคำพูดที่ชัด', 'ล้นหรือจบแบบกระแทก แบกมากเกิน หรือวัฏจักรปิดแบบเละ วางลง จัดการ ปิดให้สะอาด อากาศกลายเป็นใบมีดหันเข้าใน คิดมาก พูดกับตัวเองแรงๆ หรือคำพูดที่เรียกคืนไม่ได้', 'พูดความจริงอย่างอ่อนโยน ความชัดคือความใจดีตรงนี้', 'วิเคราะห์ สัญญา กลยุทธ์ คิดให้ครบ', 'ตัดสินใจด้วยตัวเลข ไม่ใช่ประสาท ตัดค่าใช้จ่ายสักอย่าง', 'ทำหัวให้เงียบ นอน รับข้อมูลน้อยลง กังวลทีละเรื่อง') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (60, 'page-of-swords', 'minor', 'swords', 11, 'cards/swords-11') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (60, 'en', 'Page of Swords', '["student","message","fresh curiosity","mind"]', '["gossip","distraction","study skipped","overthinking"]', 'The eager student: a message, a new study, curiosity first — beginner''s mind, open notebook. Air cuts through: thought, truth, and clear words.', 'Distracted student: gossip over study, shiny hopping. Pick one page and actually read it. Air turned blade inward: overthinking, harsh self-talk, or words you cannot unsay.', 'Say the true thing kindly; clarity is kindness here.', 'Analysis, contracts, strategy — think it through fully.', 'Decide with numbers, not nerves; cut one cost.', 'Quiet the mind: sleep, less input, one worry at a time.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (60, 'th', 'เพจดาบ', '["นักเรียน","ข้อความ","ความอยากรู้สดๆ","ความคิด"]', '["นินทา","สิ่งรบกวน","การเรียนที่ข้าม","คิดมาก"]', 'นักเรียนที่กระตือรือร้น ข้อความ การเรียนใหม่ ความอยากรู้ก่อน ใจแบบมือใหม่ สมุดที่เปิด อากาศตัดผ่าน ความคิด ความจริง และคำพูดที่ชัด', 'นักเรียนที่วอกแวก นินทาแทนเรียน กระโดดหาของแวววาว เลือกมาสักหน้าแล้วอ่านจริง อากาศกลายเป็นใบมีดหันเข้าใน คิดมาก พูดกับตัวเองแรงๆ หรือคำพูดที่เรียกคืนไม่ได้', 'พูดความจริงอย่างอ่อนโยน ความชัดคือความใจดีตรงนี้', 'วิเคราะห์ สัญญา กลยุทธ์ คิดให้ครบ', 'ตัดสินใจด้วยตัวเลข ไม่ใช่ประสาท ตัดค่าใช้จ่ายสักอย่าง', 'ทำหัวให้เงียบ นอน รับข้อมูลน้อยลง กังวลทีละเรื่อง') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (61, 'knight-of-swords', 'minor', 'swords', 12, 'cards/swords-12') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (61, 'en', 'Knight of Swords', '["charge","quest","momentum","mind"]', '["reckless charge","hot-cold","quest drift","overthinking"]', 'The charger: full momentum toward the quest — brave, fast, all-in. Air cuts through: thought, truth, and clear words.', 'Charging past the target or blowing hot and cold: rein in, re-aim, then ride. Air turned blade inward: overthinking, harsh self-talk, or words you cannot unsay.', 'Say the true thing kindly; clarity is kindness here.', 'Analysis, contracts, strategy — think it through fully.', 'Decide with numbers, not nerves; cut one cost.', 'Quiet the mind: sleep, less input, one worry at a time.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (61, 'th', 'อัศวินดาบ', '["การพุ่ง","ภารกิจ","โมเมนตัม","ความคิด"]', '["การพุ่งที่ประมาท","ร้อนหนาว","ภารกิจที่ลอย","คิดมาก"]', 'ผู้พุ่งทะยาน โมเมนตัมเต็มสู่ภารกิจ กล้า เร็ว ทุ่มหมด อากาศตัดผ่าน ความคิด ความจริง และคำพูดที่ชัด', 'พุ่งเลยเป้าหรือร้อนๆ หนาวๆ ดึงบังเหียน เล็งใหม่ แล้วค่อยขี่ อากาศกลายเป็นใบมีดหันเข้าใน คิดมาก พูดกับตัวเองแรงๆ หรือคำพูดที่เรียกคืนไม่ได้', 'พูดความจริงอย่างอ่อนโยน ความชัดคือความใจดีตรงนี้', 'วิเคราะห์ สัญญา กลยุทธ์ คิดให้ครบ', 'ตัดสินใจด้วยตัวเลข ไม่ใช่ประสาท ตัดค่าใช้จ่ายสักอย่าง', 'ทำหัวให้เงียบ นอน รับข้อมูลน้อยลง กังวลทีละเรื่อง') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (62, 'queen-of-swords', 'minor', 'swords', 13, 'cards/swords-13') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (62, 'en', 'Queen of Swords', '["mastery within","nurturing command","trusted counsel","mind"]', '["smothering","inner drought","manipulation","overthinking"]', 'Mastery turned inward: calm command, deep care, counsel others trust. Air cuts through: thought, truth, and clear words.', 'Care curdled: smothering, martyrdom, or counsel with hooks. Refill, then lead. Air turned blade inward: overthinking, harsh self-talk, or words you cannot unsay.', 'Say the true thing kindly; clarity is kindness here.', 'Analysis, contracts, strategy — think it through fully.', 'Decide with numbers, not nerves; cut one cost.', 'Quiet the mind: sleep, less input, one worry at a time.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (62, 'th', 'ราชินีดาบ', '["ความชำนาญใน","การนำด้วยการดูแล","ที่ปรึกษาที่ไว้ใจ","ความคิด"]', '["การประคบประหงม","ความแห้งใน","การบงการ","คิดมาก"]', 'ความชำนาญหันเข้าใน การบัญชาอย่างสงบ การดูแลลึกๆ คำปรึกษาที่คนไว้ใจ อากาศตัดผ่าน ความคิด ความจริง และคำพูดที่ชัด', 'การดูแลที่เสีย ประคบประหงมเกิน เป็นเหยื่อ หรือคำปรึกษาที่มีตะขอ เติมก่อน แล้วค่อยนำ อากาศกลายเป็นใบมีดหันเข้าใน คิดมาก พูดกับตัวเองแรงๆ หรือคำพูดที่เรียกคืนไม่ได้', 'พูดความจริงอย่างอ่อนโยน ความชัดคือความใจดีตรงนี้', 'วิเคราะห์ สัญญา กลยุทธ์ คิดให้ครบ', 'ตัดสินใจด้วยตัวเลข ไม่ใช่ประสาท ตัดค่าใช้จ่ายสักอย่าง', 'ทำหัวให้เงียบ นอน รับข้อมูลน้อยลง กังวลทีละเรื่อง') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (63, 'king-of-swords', 'minor', 'swords', 14, 'cards/swords-14') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (63, 'en', 'King of Swords', '["mastery without","steady authority","legacy lead","mind"]', '["domineering","abdication","hollow crown","overthinking"]', 'Mastery turned outward: steady authority, long view, leadership that lasts. Air cuts through: thought, truth, and clear words.', 'Authority warped: domineering, checked-out, or a crown with no kingdom. Re-earn it. Air turned blade inward: overthinking, harsh self-talk, or words you cannot unsay.', 'Say the true thing kindly; clarity is kindness here.', 'Analysis, contracts, strategy — think it through fully.', 'Decide with numbers, not nerves; cut one cost.', 'Quiet the mind: sleep, less input, one worry at a time.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (63, 'th', 'ราชาดาบ', '["ความชำนาญนอก","อำนาจที่มั่นคง","การนำที่สืบต่อ","ความคิด"]', '["การครอบงำ","การสละหน้าที่","มงกุฎที่กลวง","คิดมาก"]', 'ความชำนาญหันออกนอก อำนาจที่มั่นคง มุมยาว การนำที่อยู่ยาว อากาศตัดผ่าน ความคิด ความจริง และคำพูดที่ชัด', 'อำนาจที่บิด ครอบงำ ถอนตัว หรือมงกุฎที่ไม่มีอาณาจักร กลับไปทำให้สมใหม่ อากาศกลายเป็นใบมีดหันเข้าใน คิดมาก พูดกับตัวเองแรงๆ หรือคำพูดที่เรียกคืนไม่ได้', 'พูดความจริงอย่างอ่อนโยน ความชัดคือความใจดีตรงนี้', 'วิเคราะห์ สัญญา กลยุทธ์ คิดให้ครบ', 'ตัดสินใจด้วยตัวเลข ไม่ใช่ประสาท ตัดค่าใช้จ่ายสักอย่าง', 'ทำหัวให้เงียบ นอน รับข้อมูลน้อยลง กังวลทีละเรื่อง') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (64, 'ace-of-pentacles', 'minor', 'pentacles', 1, 'cards/pentacles-01') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (64, 'en', 'Ace of Pentacles', '["seed","gift","pure potential","craft"]', '["blocked seed","missed gift","hollow start","stuck resources"]', 'A new seed in this suit''s domain — raw, bright potential. Earth builds it: craft, patience, and tangible results.', 'The seed cannot sprout yet: wrong soil, wrong season, or a gift refused. Earth hardened: stuck money, grind without rest, or health traded for hustle.', 'Show love tangibly: time kept, promises funded.', 'Craft and consistency compound; apprentice mindset.', 'The money suit: budget, save, invest boringly.', 'The body is the first asset; maintain it.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (64, 'th', 'เอซ เหรียญ', '["เมล็ด","ของขวัญ","ศักยภาพบริสุทธิ์","ฝีมือ"]', '["เมล็ดที่ติดขัด","ของขวัญที่พลาด","การเริ่มที่กลวง","ทรัพยากรที่ติด"]', 'เมล็ดใหม่ในอาณาเขตของไพ่ชุดนี้ ศักยภาพดิบที่สดใส ดินสร้างมัน ฝีมือ ความอดทน และผลที่จับต้องได้', 'เมล็ดยังงอกไม่ได้ ดินผิด ฤดูผิด หรือของขวัญที่ถูกปฏิเสธ ดินแข็งตัว เงินติด ทำงานไม่พัก หรือเอาแรงกายแลกงาน', 'แสดงความรักให้จับต้องได้ เวลาที่รักษา สัญญาที่มีทุน', 'ฝีมือและความสม่ำเสมอทบต้น ใจแบบลูกศิษย์', 'ไพ่เงิน ทำงบ เก็บ ลงทุนแบบน่าเบื่อ', 'ร่างกายคือสินทรัพย์แรก ดูแลมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (65, 'two-of-pentacles', 'minor', 'pentacles', 2, 'cards/pentacles-02') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (65, 'en', 'Two of Pentacles', '["balance","partnership","first choice","craft"]', '["imbalance","stalemate","avoided choice","stuck resources"]', 'Two forces meet: partnership, balance, or the first real choice. Earth builds it: craft, patience, and tangible results.', 'The pair is off-balance: stalemate, tension, or a choice dodged. Earth hardened: stuck money, grind without rest, or health traded for hustle.', 'Show love tangibly: time kept, promises funded.', 'Craft and consistency compound; apprentice mindset.', 'The money suit: budget, save, invest boringly.', 'The body is the first asset; maintain it.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (65, 'th', '2 เหรียญ', '["ความสมดุล","หุ้นส่วน","ทางเลือกแรก","ฝีมือ"]', '["ความไม่สมดุล","การตัน","ทางเลือกที่เลี่ยง","ทรัพยากรที่ติด"]', 'พลังสองสายมาบรรจบ หุ้นส่วน ความสมดุล หรือทางเลือกจริงครั้งแรก ดินสร้างมัน ฝีมือ ความอดทน และผลที่จับต้องได้', 'คู่นี้เสียสมดุล ตัน ตึง หรือทางเลือกที่ถูกเลี่ยง ดินแข็งตัว เงินติด ทำงานไม่พัก หรือเอาแรงกายแลกงาน', 'แสดงความรักให้จับต้องได้ เวลาที่รักษา สัญญาที่มีทุน', 'ฝีมือและความสม่ำเสมอทบต้น ใจแบบลูกศิษย์', 'ไพ่เงิน ทำงบ เก็บ ลงทุนแบบน่าเบื่อ', 'ร่างกายคือสินทรัพย์แรก ดูแลมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (66, 'three-of-pentacles', 'minor', 'pentacles', 3, 'cards/pentacles-03') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (66, 'en', 'Three of Pentacles', '["first fruits","togetherness","expression","craft"]', '["scattered trio","gossip","delayed fruits","stuck resources"]', 'First fruits: growth shows, people gather, expression flows. Earth builds it: craft, patience, and tangible results.', 'The trio frays: miscommunication, gossip, or fruits that need more season. Earth hardened: stuck money, grind without rest, or health traded for hustle.', 'Show love tangibly: time kept, promises funded.', 'Craft and consistency compound; apprentice mindset.', 'The money suit: budget, save, invest boringly.', 'The body is the first asset; maintain it.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (66, 'th', '3 เหรียญ', '["ผลแรก","ความพร้อมหน้า","การแสดงออก","ฝีมือ"]', '["สามคนที่แตก","นินทา","ผลที่ช้า","ทรัพยากรที่ติด"]', 'ผลแรก ความเติบโตเริ่มเห็น คนรวมกัน การแสดงออกไหล ดินสร้างมัน ฝีมือ ความอดทน และผลที่จับต้องได้', 'สามคนเริ่มขาด การสื่อสารพลาด นินทา หรือผลที่ต้องรอฤดูอีกหน่อย ดินแข็งตัว เงินติด ทำงานไม่พัก หรือเอาแรงกายแลกงาน', 'แสดงความรักให้จับต้องได้ เวลาที่รักษา สัญญาที่มีทุน', 'ฝีมือและความสม่ำเสมอทบต้น ใจแบบลูกศิษย์', 'ไพ่เงิน ทำงบ เก็บ ลงทุนแบบน่าเบื่อ', 'ร่างกายคือสินทรัพย์แรก ดูแลมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (67, 'four-of-pentacles', 'minor', 'pentacles', 4, 'cards/pentacles-04') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (67, 'en', 'Four of Pentacles', '["rest","foundation","pause to hold","craft"]', '["stagnation","rigid hold","rest refused","stuck resources"]', 'Four walls: rest, consolidate, hold what you built. Earth builds it: craft, patience, and tangible results.', 'Rest curdled into rut: clinging to the walls instead of living in the house. Earth hardened: stuck money, grind without rest, or health traded for hustle.', 'Show love tangibly: time kept, promises funded.', 'Craft and consistency compound; apprentice mindset.', 'The money suit: budget, save, invest boringly.', 'The body is the first asset; maintain it.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (67, 'th', '4 เหรียญ', '["การพัก","รากฐาน","การหยุดเพื่อรักษา","ฝีมือ"]', '["การนิ่งตาย","การยึดแข็ง","การปฏิเสธการพัก","ทรัพยากรที่ติด"]', 'กำแพงสี่ด้าน พัก ประสาน รักษาสิ่งที่สร้างมา ดินสร้างมัน ฝีมือ ความอดทน และผลที่จับต้องได้', 'การพักกลายเป็นร่อง ยึดกำแพงแทนที่จะอยู่ในบ้าน ดินแข็งตัว เงินติด ทำงานไม่พัก หรือเอาแรงกายแลกงาน', 'แสดงความรักให้จับต้องได้ เวลาที่รักษา สัญญาที่มีทุน', 'ฝีมือและความสม่ำเสมอทบต้น ใจแบบลูกศิษย์', 'ไพ่เงิน ทำงบ เก็บ ลงทุนแบบน่าเบื่อ', 'ร่างกายคือสินทรัพย์แรก ดูแลมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (68, 'five-of-pentacles', 'minor', 'pentacles', 5, 'cards/pentacles-05') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (68, 'en', 'Five of Pentacles', '["friction","loss felt","shake-up","craft"]', '["longer conflict","blame","slow recovery","stuck resources"]', 'Friction with a lesson: loss, conflict, or a shake-up that reveals what stands. Earth builds it: craft, patience, and tangible results.', 'The fight drags on or blame spreads; recovery is slow but possible — stop feeding it. Earth hardened: stuck money, grind without rest, or health traded for hustle.', 'Show love tangibly: time kept, promises funded.', 'Craft and consistency compound; apprentice mindset.', 'The money suit: budget, save, invest boringly.', 'The body is the first asset; maintain it.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (68, 'th', '5 เหรียญ', '["แรงเสียดทาน","ความสูญเสียที่รู้สึก","แรงเขย่า","ฝีมือ"]', '["ความขัดแย้งที่ยาว","การโทษ","การฟื้นช้า","ทรัพยากรที่ติด"]', 'แรงเสียดทานพร้อมบทเรียน ความสูญเสีย ความขัดแย้ง หรือแรงเขย่าที่เผยให้เห็นสิ่งที่ยืนอยู่ ดินสร้างมัน ฝีมือ ความอดทน และผลที่จับต้องได้', 'การสู้ยืดเยื้อหรือการโทษกันลาม การฟื้นช้าแต่เป็นไปได้ เลิกให้อาหารมัน ดินแข็งตัว เงินติด ทำงานไม่พัก หรือเอาแรงกายแลกงาน', 'แสดงความรักให้จับต้องได้ เวลาที่รักษา สัญญาที่มีทุน', 'ฝีมือและความสม่ำเสมอทบต้น ใจแบบลูกศิษย์', 'ไพ่เงิน ทำงบ เก็บ ลงทุนแบบน่าเบื่อ', 'ร่างกายคือสินทรัพย์แรก ดูแลมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (69, 'six-of-pentacles', 'minor', 'pentacles', 6, 'cards/pentacles-06') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (69, 'en', 'Six of Pentacles', '["ease after strain","giving","nostalgia","craft"]', '["strings attached","stuck past","unequal give","stuck resources"]', 'Breathing room: help given or received, sweetness from the past, smoother water. Earth builds it: craft, patience, and tangible results.', 'Giving with strings, or living in the rearview: accept help cleanly, visit the past — do not move back in. Earth hardened: stuck money, grind without rest, or health traded for hustle.', 'Show love tangibly: time kept, promises funded.', 'Craft and consistency compound; apprentice mindset.', 'The money suit: budget, save, invest boringly.', 'The body is the first asset; maintain it.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (69, 'th', '6 เหรียญ', '["ความโล่งหลังเหนื่อย","การให้","ความคิดถึง","ฝีมือ"]', '["เงื่อนไขที่ผูก","อดีตที่ติด","การให้ที่ไม่เท่า","ทรัพยากรที่ติด"]', 'ที่หายใจ ความช่วยเหลือที่ให้หรือรับ ความหวานจากอดีต น้ำที่เรียบขึ้น ดินสร้างมัน ฝีมือ ความอดทน และผลที่จับต้องได้', 'ให้แบบมีเงื่อนไข หรืออยู่ในกระจกมองหลัง รับความช่วยเหลืออย่างสะอาด แวะอดีต อย่าย้ายกลับเข้าไป ดินแข็งตัว เงินติด ทำงานไม่พัก หรือเอาแรงกายแลกงาน', 'แสดงความรักให้จับต้องได้ เวลาที่รักษา สัญญาที่มีทุน', 'ฝีมือและความสม่ำเสมอทบต้น ใจแบบลูกศิษย์', 'ไพ่เงิน ทำงบ เก็บ ลงทุนแบบน่าเบื่อ', 'ร่างกายคือสินทรัพย์แรก ดูแลมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (70, 'seven-of-pentacles', 'minor', 'pentacles', 7, 'cards/pentacles-07') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (70, 'en', 'Seven of Pentacles', '["assessment","many options","stand your ground","craft"]', '["overwhelm","illusion of choice","defensive crouch","stuck resources"]', 'Step back and assess: many options, one position to defend, patience before the next move. Earth builds it: craft, patience, and tangible results.', 'Too many threads or a defensive crouch: narrow the field, then stand — or strategically yield. Earth hardened: stuck money, grind without rest, or health traded for hustle.', 'Show love tangibly: time kept, promises funded.', 'Craft and consistency compound; apprentice mindset.', 'The money suit: budget, save, invest boringly.', 'The body is the first asset; maintain it.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (70, 'th', '7 เหรียญ', '["การประเมิน","ทางเลือกมาก","รักษาที่ยืน","ฝีมือ"]', '["ความท่วมท้น","ภาพลวงของทางเลือก","ท่าตั้งรับ","ทรัพยากรที่ติด"]', 'ถอยมาประเมิน ทางเลือกมาก ที่ยืนที่ต้องรักษา อดทนก่อนขยับต่อไป ดินสร้างมัน ฝีมือ ความอดทน และผลที่จับต้องได้', 'ด้ายมากเกินไปหรือท่าตั้งรับ แคบสนามลง แล้วค่อยยืน หรือถอยอย่างมีกลยุทธ์ ดินแข็งตัว เงินติด ทำงานไม่พัก หรือเอาแรงกายแลกงาน', 'แสดงความรักให้จับต้องได้ เวลาที่รักษา สัญญาที่มีทุน', 'ฝีมือและความสม่ำเสมอทบต้น ใจแบบลูกศิษย์', 'ไพ่เงิน ทำงบ เก็บ ลงทุนแบบน่าเบื่อ', 'ร่างกายคือสินทรัพย์แรก ดูแลมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (71, 'eight-of-pentacles', 'minor', 'pentacles', 8, 'cards/pentacles-08') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (71, 'en', 'Eight of Pentacles', '["mastery in motion","focused work","swift change","craft"]', '["scattered effort","perfectionism","too fast","stuck resources"]', 'Skilled motion: focused work compounds, or change arrives fast — meet it prepared. Earth builds it: craft, patience, and tangible results.', 'Effort scattered or perfectionism stalling the line; slow one thing down to speed the whole up. Earth hardened: stuck money, grind without rest, or health traded for hustle.', 'Show love tangibly: time kept, promises funded.', 'Craft and consistency compound; apprentice mindset.', 'The money suit: budget, save, invest boringly.', 'The body is the first asset; maintain it.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (71, 'th', '8 เหรียญ', '["ความชำนาญที่เคลื่อน","งานโฟกัส","การเปลี่ยนที่เร็ว","ฝีมือ"]', '["ความพยายามที่แตก","ความสมบูรณ์แบบ","เร็วเกินไป","ทรัพยากรที่ติด"]', 'การเคลื่อนอย่างชำนาญ งานโฟกัสทบต้น หรือการเปลี่ยนมาเร็ว เจอมันอย่างเตรียมพร้อม ดินสร้างมัน ฝีมือ ความอดทน และผลที่จับต้องได้', 'ความพยายามกระจัดกระจายหรือความสมบูรณ์แบบทำให้สายพานหยุด ชะลอสิ่งหนึ่งเพื่อให้ทั้งหมดเร็วขึ้น ดินแข็งตัว เงินติด ทำงานไม่พัก หรือเอาแรงกายแลกงาน', 'แสดงความรักให้จับต้องได้ เวลาที่รักษา สัญญาที่มีทุน', 'ฝีมือและความสม่ำเสมอทบต้น ใจแบบลูกศิษย์', 'ไพ่เงิน ทำงบ เก็บ ลงทุนแบบน่าเบื่อ', 'ร่างกายคือสินทรัพย์แรก ดูแลมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (72, 'nine-of-pentacles', 'minor', 'pentacles', 9, 'cards/pentacles-09') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (72, 'en', 'Nine of Pentacles', '["near-complete","wishes","resilience","craft"]', '["nearly-but-stuck","anxiety nights","walled garden","stuck resources"]', 'Almost whole: wishes close, resilience proven — guard the last stretch with care. Earth builds it: craft, patience, and tangible results.', 'So close yet stuck: worry loops or a comfort zone fenced too high. Name the fear, take the final step. Earth hardened: stuck money, grind without rest, or health traded for hustle.', 'Show love tangibly: time kept, promises funded.', 'Craft and consistency compound; apprentice mindset.', 'The money suit: budget, save, invest boringly.', 'The body is the first asset; maintain it.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (72, 'th', '9 เหรียญ', '["เกือบสมบูรณ์","ความปรารถนา","ความอึด","ฝีมือ"]', '["เกือบแต่ติด","คืนที่นอนไม่หลับ","สวนที่มีกำแพง","ทรัพยากรที่ติด"]', 'เกือบครบ ความปรารถนาใกล้ ความอึดพิสูจน์แล้ว ประคองช่วงสุดท้ายดีๆ ดินสร้างมัน ฝีมือ ความอดทน และผลที่จับต้องได้', 'ใกล้แต่ติด วงจรความกังวลหรือเขตสบายที่รั้วสูงไป ตั้งชื่อความกลัว แล้วก้าวสุดท้าย ดินแข็งตัว เงินติด ทำงานไม่พัก หรือเอาแรงกายแลกงาน', 'แสดงความรักให้จับต้องได้ เวลาที่รักษา สัญญาที่มีทุน', 'ฝีมือและความสม่ำเสมอทบต้น ใจแบบลูกศิษย์', 'ไพ่เงิน ทำงบ เก็บ ลงทุนแบบน่าเบื่อ', 'ร่างกายคือสินทรัพย์แรก ดูแลมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (73, 'ten-of-pentacles', 'minor', 'pentacles', 10, 'cards/pentacles-10') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (73, 'en', 'Ten of Pentacles', '["completion","full circle","legacy","craft"]', '["overfull","crashing end","burden shared badly","stuck resources"]', 'The full arc of the suit: completion, culmination, what carries forward. Earth builds it: craft, patience, and tangible results.', 'Overfull or ending hard: too much carried, or a cycle closing messily — set down, sort out, close clean. Earth hardened: stuck money, grind without rest, or health traded for hustle.', 'Show love tangibly: time kept, promises funded.', 'Craft and consistency compound; apprentice mindset.', 'The money suit: budget, save, invest boringly.', 'The body is the first asset; maintain it.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (73, 'th', '10 เหรียญ', '["ความสมบูรณ์","วงเต็ม","มรดก","ฝีมือ"]', '["ล้นเกิน","จุดจบที่กระแทก","ภาระที่แบ่งไม่ดี","ทรัพยากรที่ติด"]', 'ส่วนโค้งเต็มของไพ่ชุดนี้ ความสมบูรณ์ จุดสูงสุด สิ่งที่ส่งต่อ ดินสร้างมัน ฝีมือ ความอดทน และผลที่จับต้องได้', 'ล้นหรือจบแบบกระแทก แบกมากเกิน หรือวัฏจักรปิดแบบเละ วางลง จัดการ ปิดให้สะอาด ดินแข็งตัว เงินติด ทำงานไม่พัก หรือเอาแรงกายแลกงาน', 'แสดงความรักให้จับต้องได้ เวลาที่รักษา สัญญาที่มีทุน', 'ฝีมือและความสม่ำเสมอทบต้น ใจแบบลูกศิษย์', 'ไพ่เงิน ทำงบ เก็บ ลงทุนแบบน่าเบื่อ', 'ร่างกายคือสินทรัพย์แรก ดูแลมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (74, 'page-of-pentacles', 'minor', 'pentacles', 11, 'cards/pentacles-11') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (74, 'en', 'Page of Pentacles', '["student","message","fresh curiosity","craft"]', '["gossip","distraction","study skipped","stuck resources"]', 'The eager student: a message, a new study, curiosity first — beginner''s mind, open notebook. Earth builds it: craft, patience, and tangible results.', 'Distracted student: gossip over study, shiny hopping. Pick one page and actually read it. Earth hardened: stuck money, grind without rest, or health traded for hustle.', 'Show love tangibly: time kept, promises funded.', 'Craft and consistency compound; apprentice mindset.', 'The money suit: budget, save, invest boringly.', 'The body is the first asset; maintain it.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (74, 'th', 'เพจเหรียญ', '["นักเรียน","ข้อความ","ความอยากรู้สดๆ","ฝีมือ"]', '["นินทา","สิ่งรบกวน","การเรียนที่ข้าม","ทรัพยากรที่ติด"]', 'นักเรียนที่กระตือรือร้น ข้อความ การเรียนใหม่ ความอยากรู้ก่อน ใจแบบมือใหม่ สมุดที่เปิด ดินสร้างมัน ฝีมือ ความอดทน และผลที่จับต้องได้', 'นักเรียนที่วอกแวก นินทาแทนเรียน กระโดดหาของแวววาว เลือกมาสักหน้าแล้วอ่านจริง ดินแข็งตัว เงินติด ทำงานไม่พัก หรือเอาแรงกายแลกงาน', 'แสดงความรักให้จับต้องได้ เวลาที่รักษา สัญญาที่มีทุน', 'ฝีมือและความสม่ำเสมอทบต้น ใจแบบลูกศิษย์', 'ไพ่เงิน ทำงบ เก็บ ลงทุนแบบน่าเบื่อ', 'ร่างกายคือสินทรัพย์แรก ดูแลมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (75, 'knight-of-pentacles', 'minor', 'pentacles', 12, 'cards/pentacles-12') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (75, 'en', 'Knight of Pentacles', '["charge","quest","momentum","craft"]', '["reckless charge","hot-cold","quest drift","stuck resources"]', 'The charger: full momentum toward the quest — brave, fast, all-in. Earth builds it: craft, patience, and tangible results.', 'Charging past the target or blowing hot and cold: rein in, re-aim, then ride. Earth hardened: stuck money, grind without rest, or health traded for hustle.', 'Show love tangibly: time kept, promises funded.', 'Craft and consistency compound; apprentice mindset.', 'The money suit: budget, save, invest boringly.', 'The body is the first asset; maintain it.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (75, 'th', 'อัศวินเหรียญ', '["การพุ่ง","ภารกิจ","โมเมนตัม","ฝีมือ"]', '["การพุ่งที่ประมาท","ร้อนหนาว","ภารกิจที่ลอย","ทรัพยากรที่ติด"]', 'ผู้พุ่งทะยาน โมเมนตัมเต็มสู่ภารกิจ กล้า เร็ว ทุ่มหมด ดินสร้างมัน ฝีมือ ความอดทน และผลที่จับต้องได้', 'พุ่งเลยเป้าหรือร้อนๆ หนาวๆ ดึงบังเหียน เล็งใหม่ แล้วค่อยขี่ ดินแข็งตัว เงินติด ทำงานไม่พัก หรือเอาแรงกายแลกงาน', 'แสดงความรักให้จับต้องได้ เวลาที่รักษา สัญญาที่มีทุน', 'ฝีมือและความสม่ำเสมอทบต้น ใจแบบลูกศิษย์', 'ไพ่เงิน ทำงบ เก็บ ลงทุนแบบน่าเบื่อ', 'ร่างกายคือสินทรัพย์แรก ดูแลมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (76, 'queen-of-pentacles', 'minor', 'pentacles', 13, 'cards/pentacles-13') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (76, 'en', 'Queen of Pentacles', '["mastery within","nurturing command","trusted counsel","craft"]', '["smothering","inner drought","manipulation","stuck resources"]', 'Mastery turned inward: calm command, deep care, counsel others trust. Earth builds it: craft, patience, and tangible results.', 'Care curdled: smothering, martyrdom, or counsel with hooks. Refill, then lead. Earth hardened: stuck money, grind without rest, or health traded for hustle.', 'Show love tangibly: time kept, promises funded.', 'Craft and consistency compound; apprentice mindset.', 'The money suit: budget, save, invest boringly.', 'The body is the first asset; maintain it.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (76, 'th', 'ราชินีเหรียญ', '["ความชำนาญใน","การนำด้วยการดูแล","ที่ปรึกษาที่ไว้ใจ","ฝีมือ"]', '["การประคบประหงม","ความแห้งใน","การบงการ","ทรัพยากรที่ติด"]', 'ความชำนาญหันเข้าใน การบัญชาอย่างสงบ การดูแลลึกๆ คำปรึกษาที่คนไว้ใจ ดินสร้างมัน ฝีมือ ความอดทน และผลที่จับต้องได้', 'การดูแลที่เสีย ประคบประหงมเกิน เป็นเหยื่อ หรือคำปรึกษาที่มีตะขอ เติมก่อน แล้วค่อยนำ ดินแข็งตัว เงินติด ทำงานไม่พัก หรือเอาแรงกายแลกงาน', 'แสดงความรักให้จับต้องได้ เวลาที่รักษา สัญญาที่มีทุน', 'ฝีมือและความสม่ำเสมอทบต้น ใจแบบลูกศิษย์', 'ไพ่เงิน ทำงบ เก็บ ลงทุนแบบน่าเบื่อ', 'ร่างกายคือสินทรัพย์แรก ดูแลมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO cards (id, slug, arcana, suit, rank, image_key) VALUES (77, 'king-of-pentacles', 'minor', 'pentacles', 14, 'cards/pentacles-14') ON CONFLICT (id) DO UPDATE SET slug=excluded.slug, arcana=excluded.arcana, suit=excluded.suit, rank=excluded.rank, image_key=excluded.image_key;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (77, 'en', 'King of Pentacles', '["mastery without","steady authority","legacy lead","craft"]', '["domineering","abdication","hollow crown","stuck resources"]', 'Mastery turned outward: steady authority, long view, leadership that lasts. Earth builds it: craft, patience, and tangible results.', 'Authority warped: domineering, checked-out, or a crown with no kingdom. Re-earn it. Earth hardened: stuck money, grind without rest, or health traded for hustle.', 'Show love tangibly: time kept, promises funded.', 'Craft and consistency compound; apprentice mindset.', 'The money suit: budget, save, invest boringly.', 'The body is the first asset; maintain it.') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
INSERT INTO card_meanings (card_id, lang, name, keywords_upright, keywords_reversed, upright, reversed, love, career, money, health) VALUES (77, 'th', 'ราชาเหรียญ', '["ความชำนาญนอก","อำนาจที่มั่นคง","การนำที่สืบต่อ","ฝีมือ"]', '["การครอบงำ","การสละหน้าที่","มงกุฎที่กลวง","ทรัพยากรที่ติด"]', 'ความชำนาญหันออกนอก อำนาจที่มั่นคง มุมยาว การนำที่อยู่ยาว ดินสร้างมัน ฝีมือ ความอดทน และผลที่จับต้องได้', 'อำนาจที่บิด ครอบงำ ถอนตัว หรือมงกุฎที่ไม่มีอาณาจักร กลับไปทำให้สมใหม่ ดินแข็งตัว เงินติด ทำงานไม่พัก หรือเอาแรงกายแลกงาน', 'แสดงความรักให้จับต้องได้ เวลาที่รักษา สัญญาที่มีทุน', 'ฝีมือและความสม่ำเสมอทบต้น ใจแบบลูกศิษย์', 'ไพ่เงิน ทำงบ เก็บ ลงทุนแบบน่าเบื่อ', 'ร่างกายคือสินทรัพย์แรก ดูแลมัน') ON CONFLICT (card_id, lang) DO UPDATE SET name=excluded.name, keywords_upright=excluded.keywords_upright, keywords_reversed=excluded.keywords_reversed, upright=excluded.upright, reversed=excluded.reversed, love=excluded.love, career=excluded.career, money=excluded.money, health=excluded.health;
